#[derive(Clone, Debug)]
struct CliOptions {
    no_antialias: bool,
    background: Color,
    background_raw: Option<String>,
    debug: bool,
    no_separation: bool,
    encoding: Option<String>,
    html: bool,
    overwrite: bool,
    round_corners: bool,
    no_shadows: bool,
    scale: f32,
    transparent: bool,
    tabs: usize,
    verbose: bool,
    fixed_slope: bool,
    svg: bool,
    svg_font_url: Option<String>,
    positional: Vec<String>,
    reported_options: Vec<String>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Color {
    r: u8,
    g: u8,
    b: u8,
    a: u8,
}

impl Color {
    const fn rgb(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b, a: 255 }
    }

    fn hex_rgb(self) -> String {
        format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
    }

    fn luminance(self) -> f32 {
        0.2126 * self.r as f32 + 0.7152 * self.g as f32 + 0.0722 * self.b as f32
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ShapeKind {
    Rect,
    Document,
    Storage,
    Ellipse,
    ManualOperation,
    Decision,
    Trapezoid,
    Io,
}

#[derive(Clone, Debug)]
struct Shape {
    x0: i32,
    y0: i32,
    x1: i32,
    y1: i32,
