    bullet: bool,
}

#[derive(Clone, Debug)]
struct LooseText {
    row: i32,
    start: i32,
    end: i32,
    text: String,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct Point {
    x: i32,
    y: i32,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct Edge {
    a: Point,
    b: Point,
}

impl Edge {
    fn new(a: Point, b: Point) -> Self {
        if (a.x, a.y) <= (b.x, b.y) {
            Self { a, b }
        } else {
            Self { a: b, b: a }
        }
    }
}

#[derive(Clone, Debug)]
struct StrokePath {
