    loose_text: Vec<LooseText>,
    separations: Vec<Separation>,
}

enum ParseOutcome {
    Usage,
    WeirdJar,
    Run(CliOptions),
}

struct CliError {
    message: String,
    code: i32,
    show_usage: bool,
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match parse_args(&args) {
        Ok(ParseOutcome::Usage) => {
            println!("{USAGE}");
        }
        Ok(ParseOutcome::WeirdJar) => {
            eprintln!("{JAR_ERROR}");
            process::exit(1);
        }
        Ok(ParseOutcome::Run(options)) => {
            let code = match run(options) {
                Ok(code) => code,
                Err(err) => {
                    eprintln!("Error: {err:#}");
                    1
                }
            };
            process::exit(code);
        }
        Err(err) => {
            eprintln!("{}", err.message);
            if err.show_usage {
                println!("{USAGE}");
            }
            process::exit(err.code);
        }
    }
}

fn parse_args(args: &[String]) -> Result<ParseOutcome, CliError> {
    if args.is_empty() {
        return Ok(ParseOutcome::Usage);
    }
    if args.len() == 1 && matches!(args[0].as_str(), "--help" | "-h") {
        return Ok(ParseOutcome::WeirdJar);
    }
    if args.iter().any(|arg| arg == "--help") {
        return Ok(ParseOutcome::Usage);
    }

    let mut options = CliOptions {
        no_antialias: false,
        background: Color::rgb(255, 255, 255),
        background_raw: None,
        debug: false,
        no_separation: false,
        encoding: None,
        html: false,
        overwrite: false,
        round_corners: false,
        no_shadows: false,
        scale: 1.0,
        transparent: false,
        tabs: 8,
        verbose: false,
        fixed_slope: false,
        svg: false,
        svg_font_url: None,
        positional: Vec::new(),
        reported_options: Vec::new(),
    };

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-A" | "--no-antialias" => {
                options.no_antialias = true;
                options.reported_options.push("no-antialias".to_string());
            }
            "-b" | "--background" => {
                let value = args.get(i + 1).ok_or_else(|| CliError {
                    message: "Missing argument for option: -b".to_string(),
                    code: 2,
                    show_usage: true,
                })?;
                let color = parse_background(value)?;
                options.background = color;
                options.background_raw = Some(value.clone());
                options
                    .reported_options
                    .push(format!("background = {}", value));
                i += 1;
            }
            "-d" | "--debug" => {
                options.debug = true;
                options.reported_options.push("debug".to_string());
            }
            "-E" | "--no-separation" => {
                options.no_separation = true;
                options.reported_options.push("no-separation".to_string());
            }
            "-e" | "--encoding" => {
                let value = args.get(i + 1).ok_or_else(|| CliError {
                    message: "Missing argument for option: -e".to_string(),
                    code: 2,
                    show_usage: true,
                })?;
                options.encoding = Some(value.clone());
                options
                    .reported_options
                    .push(format!("encoding = {}", value));
                i += 1;
            }
            "-h" | "--html" => {
                options.html = true;
                options.reported_options.push("html".to_string());
            }
            "-o" | "--overwrite" => {
                options.overwrite = true;
                options.reported_options.push("overwrite".to_string());
            }
            "-r" | "--round-corners" => {
                options.round_corners = true;
                options.reported_options.push("round-corners".to_string());
            }
            "-S" | "--no-shadows" => {
                options.no_shadows = true;
                options.reported_options.push("no-shadows".to_string());
            }
            "-s" | "--scale" => {
                let value = args.get(i + 1).ok_or_else(|| CliError {
                    message: "Missing argument for option: -s".to_string(),
                    code: 2,
                    show_usage: true,
                })?;
                let parsed = value.parse::<f32>().map_err(|_| CliError {
                    message: format!("Error: For input string: \"{}\"", value),
                    code: 2,
                    show_usage: true,
                })?;
                options.scale = parsed;
                options.reported_options.push(format!("scale = {}", value));
                i += 1;
            }
            "--svg" => {
                options.svg = true;
                options.reported_options.push("svg".to_string());
            }
            "--svg-font-url" => {
                let value = args.get(i + 1).ok_or_else(|| CliError {
                    message: "Missing argument for option: --svg-font-url".to_string(),
                    code: 2,
                    show_usage: true,
                })?;
                options.svg_font_url = Some(value.clone());
                options
                    .reported_options
                    .push(format!("svg-font-url = {}", value));
                i += 1;
            }
            "-T" | "--transparent" => {
                options.transparent = true;
                options.reported_options.push("transparent".to_string());
            }
            "-t" | "--tabs" => {
                let value = args.get(i + 1).ok_or_else(|| CliError {
                    message: "Missing argument for option: -t".to_string(),
                    code: 2,
                    show_usage: true,
                })?;
                let parsed = value.parse::<usize>().map_err(|_| CliError {
                    message: format!("Error: For input string: \"{}\"", value),
                    code: 2,
                    show_usage: true,
                })?;
                options.tabs = parsed;
                options.reported_options.push(format!("tabs = {}", value));
                i += 1;
            }
            "-v" | "--verbose" => {
                options.verbose = true;
                options.reported_options.push("verbose".to_string());
            }
            "-W" | "--fixed-slope" => {
                options.fixed_slope = true;
                options.reported_options.push("fixed-slope".to_string());
            }
            _ if arg.starts_with('-') => {
                return Err(CliError {
                    message: format!("Unrecognized option: {}", arg),
                    code: 2,
                    show_usage: true,
                });
            }
            _ => {
                if options.positional.len() < 2 {
                    options.positional.push(arg.clone());
                }
            }
        }
        i += 1;
    }

    if options.positional.is_empty() {
        return Ok(ParseOutcome::Usage);
    }
    Ok(ParseOutcome::Run(options))
}

fn parse_background(value: &str) -> Result<Color, CliError> {
    let ok_len = value.len() == 6 || value.len() == 8;
    let ok_hex = value.chars().all(|c| c.is_ascii_hexdigit());
    if !ok_len || !ok_hex {
        return Err(CliError {
            message: format!(
                "Error: Cannot interpret \"{}\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).",
                value
            ),
            code: 2,
            show_usage: true,
        });
    }
    let hex = u32::from_str_radix(value, 16).map_err(|_| CliError {
        message: format!(
            "Error: Cannot interpret \"{}\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).",
            value
        ),
        code: 2,
        show_usage: true,
    })?;
    let color = if value.len() == 6 {
        Color {
            r: ((hex >> 16) & 0xff) as u8,
            g: ((hex >> 8) & 0xff) as u8,
            b: (hex & 0xff) as u8,
            a: 255,
        }
    } else {
        Color {
            r: ((hex >> 24) & 0xff) as u8,
            g: ((hex >> 16) & 0xff) as u8,
            b: ((hex >> 8) & 0xff) as u8,
            a: (hex & 0xff) as u8,
        }
    };
    Ok(color)
}

fn run(options: CliOptions) -> Result<i32> {
    print_banner(&options.reported_options);
    if options.html {
        run_html(&options)?;
    } else {
        run_diagram(&options)?;
    }
    Ok(0)
}

fn print_banner(reported_options: &[String]) {
    println!();
    println!("{VERSION}");
    println!();
    println!("Running with options:");
    for option in reported_options {
        println!("{option}");
    }
}

fn run_diagram(options: &CliOptions) -> Result<()> {
    let input = Path::new(&options.positional[0]);
    println!("Reading file: {}", input.display());
    let lines = read_lines(input, options)?;
    if options.verbose {
        print_verbose_grid(&lines);
    }
    let output = if let Some(path) = options.positional.get(1) {
        PathBuf::from(path)
    } else {
        derive_diagram_output(input, options.svg, options.overwrite)
    };
    println!("Rendering to file: {}", output.display());
    let diagram = build_diagram(&lines, options);
    if options.svg {
        let svg = render_svg(&diagram, options, false);
        fs::write(&output, svg).with_context(|| format!("writing {}", output.display()))?;
    } else {
        let svg = render_svg(&diagram, options, true);
        render_png(&svg, &output)?;
    }
    println!("Done in 0sec");
    Ok(())
}

fn run_html(options: &CliOptions) -> Result<()> {
    let input = Path::new(&options.positional[0]);
    let output = if let Some(path) = options.positional.get(1) {
        PathBuf::from(path)
    } else {
        derive_html_output(input)
    };
    if output.exists() && !options.overwrite {
        println!(
            "Error: File {} exists. If you would like to overwrite it, please use the --overwrite option.",
            output.display()
        );
        return Ok(());
    }

    let html = read_text(input, options)?;
    let pre_re = Regex::new(r"(?is)<pre\b([^>]*)>(.*?)</pre>").unwrap();
    let class_re = Regex::new(r#"(?i)\bclass\s*=\s*"([^"]*)""#).unwrap();
    let id_re = Regex::new(r#"(?i)\bid\s*=\s*"([^"]+)""#).unwrap();

    let output_dir = output
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let images_dir = output_dir.join("images");
    fs::create_dir_all(&images_dir)
        .with_context(|| format!("creating {}", images_dir.display()))?;

    let mut diagrams = Vec::new();
    let mut next_index = 1usize;
    let processed = pre_re.replace_all(&html, |caps: &regex::Captures<'_>| {
        let attrs = caps.get(1).map_or("", |m| m.as_str());
        let class_name = class_re
            .captures(attrs)
            .and_then(|cap| cap.get(1))
            .map(|m| m.as_str().to_string())
            .unwrap_or_default();
        if !class_name
            .split_whitespace()
            .any(|name| name.eq_ignore_ascii_case("textdiagram"))
        {
            return caps.get(0).unwrap().as_str().to_string();
        }
        let id = id_re
            .captures(attrs)
            .and_then(|cap| cap.get(1))
            .map(|m| m.as_str().to_string());
        let name = id.unwrap_or_else(|| {
            let value = format!("ditaa_diagram_{}", next_index);
            next_index += 1;
            value
        });
        diagrams.push((name.clone(), caps.get(2).map_or("", |m| m.as_str()).to_string()));
        format!("<img src=\"images/{}.png\" />", name)
    });

    println!(
        "Converting HTML file ({} -> {})... done",
        input.display(),
        output.display()
    );
    fs::write(&output, processed.as_ref())
        .with_context(|| format!("writing {}", output.display()))?;

    println!("Generating diagrams... ");
    for (name, text) in diagrams {
        let image = images_dir.join(format!("{name}.png"));
        if image.exists() && !options.overwrite {
            println!(
                "Error: Cannot overwrite file images/{}.png, file already exists. Use the --overwrite option if you would like to allow file overwrite.",
                name
            );
            continue;
        }
        let lines = normalize_lines(&text, options.tabs);
        let diagram = build_diagram(&lines, options);
        let svg = render_svg(&diagram, options, true);
        render_png(&svg, &image)?;
        println!("\t{}", image.display());
    }
    println!();
    println!("...done");
    Ok(())
}

fn read_lines(path: &Path, options: &CliOptions) -> Result<Vec<String>> {
    if !path.exists() {
        println!("Error: File {} does not exist", path.display());
        process::exit(1);
    }
    let text = read_text(path, options)?;
    Ok(normalize_lines(&text, options.tabs))
}

fn read_text(path: &Path, options: &CliOptions) -> Result<String> {
    if !path.exists() {
        return Err(anyhow!("File {} does not exist", path.display()));
    }
    let bytes = fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    if let Some(label) = &options.encoding {
        let encoding = Encoding::for_label(label.as_bytes())
            .ok_or_else(|| anyhow!("unknown encoding: {}", label))?;
        let (text, _, _) = encoding.decode(&bytes);
        Ok(text.into_owned())
    } else {
        Ok(String::from_utf8_lossy(&bytes).into_owned())
    }
}

fn normalize_lines(text: &str, tabs: usize) -> Vec<String> {
    let mut lines: Vec<String> = text
        .replace('\r', "")
        .split('\n')
        .map(|line| expand_tabs(line, tabs))
        .collect();
    if lines.last().is_some_and(|line| line.is_empty()) {
        lines.pop();
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

fn expand_tabs(line: &str, tabs: usize) -> String {
    let mut out = String::new();
    let tabstop = tabs.max(1);
    for ch in line.chars() {
        if ch == '\t' {
            let spaces = tabstop - (out.chars().count() % tabstop);
            for _ in 0..spaces {
                out.push(' ');
            }
        } else {
            out.push(ch);
        }
    }
    out
}

fn derive_diagram_output(input: &Path, svg: bool, overwrite: bool) -> PathBuf {
    let ext = if svg { "svg" } else { "png" };
    let mut base = replace_extension(input, ext);
    if overwrite || !base.exists() {
        return base;
    }
    let stem = input
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "output".to_string());
    let parent = input.parent().map(Path::to_path_buf).unwrap_or_default();
    let mut index = 2usize;
    loop {
        let candidate = parent.join(format!("{stem}_{index}.{ext}"));
        if !candidate.exists() {
            return candidate;
        }
        index += 1;
    }
}

fn replace_extension(path: &Path, ext: &str) -> PathBuf {
    let parent = path.parent().map(Path::to_path_buf).unwrap_or_default();
    let stem = path
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.to_string_lossy().into_owned());
    parent.join(format!("{stem}.{ext}"))
}

fn derive_html_output(input: &Path) -> PathBuf {
    let parent = input.parent().map(Path::to_path_buf).unwrap_or_default();
    let stem = input
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "output".to_string());
    parent.join(format!("{stem}_processed.html"))
}

fn print_verbose_grid(lines: &[String]) {
    let width = lines.iter().map(|line| line.chars().count()).max().unwrap_or(0) + 4;
    let mut padded = Vec::new();
    padded.push(" ".repeat(width));
    padded.push(" ".repeat(width));
    for line in lines {
        let mut row = String::from("  ");
        row.push_str(line);
        let current = row.chars().count();
        if current < width {
            row.push_str(&" ".repeat(width - current));
        }
        padded.push(row);
    }
    padded.push(" ".repeat(width));
    padded.push(" ".repeat(width));

    println!("Using grid:");
    let digits: String = (0..width)
        .map(|value| char::from(b'0' + (value % 10) as u8))
        .collect();
    println!("    {digits}");
    for (index, row) in padded.iter().enumerate() {
        println!("{:2} ({})", index, row);
    }
}

fn build_diagram(lines: &[String], options: &CliOptions) -> Diagram {
    let width = lines.iter().map(|line| line.chars().count()).max().unwrap_or(0);
    let height = lines.len();
    let grid: Vec<Vec<char>> = lines
        .iter()
        .map(|line| {
            let mut chars: Vec<char> = line.chars().collect();
            chars.resize(width, ' ');
            chars
        })
        .collect();

    let marker_re = Regex::new(r"\{(d|s|o|mo|c|tr|io)\}").unwrap();
    let color_re = Regex::new(r"\bc(RED|GRE|BLU|PNK|YEL|BLK)\b").unwrap();

    let mut shapes = Vec::new();
    let mut seen_shapes = HashSet::new();
    let mut boundary_edges = HashSet::new();
    let mut interior_mask = vec![vec![false; width]; height];

    for y0 in 0..height as i32 {
        for x0 in 0..width as i32 {
            let tl = grid[y0 as usize][x0 as usize];
            if !matches!(tl, '+' | '/') {
                continue;
            }
            for x1 in (x0 + 2)..(width as i32) {
                let tr = grid[y0 as usize][x1 as usize];
                if !matches!(tr, '+' | '\\') {
                    continue;
                }
                if !(x0 + 1..x1).all(|x| is_horizontal_edge(grid[y0 as usize][x as usize])) {
                    continue;
                }
                for y1 in (y0 + 2)..(height as i32) {
                    let bl = grid[y1 as usize][x0 as usize];
                    let br = grid[y1 as usize][x1 as usize];
                    if !matches!(bl, '+' | '\\') || !matches!(br, '+' | '/') {
                        continue;
                    }
                    if !(x0 + 1..x1).all(|x| is_horizontal_edge(grid[y1 as usize][x as usize])) {
                        continue;
                    }
                    if !(y0 + 1..y1).all(|y| {
                        is_vertical_edge(grid[y as usize][x0 as usize])
                            && is_vertical_edge(grid[y as usize][x1 as usize])
                    }) {
                        continue;
                    }
                    let key = (x0, y0, x1, y1);
                    if !seen_shapes.insert(key) {
                        continue;
                    }

                    let mut raw_inside = Vec::new();
                    for y in (y0 + 1)..y1 {
                        let line: String = ((x0 + 1)..x1)
                            .map(|x| grid[y as usize][x as usize])
                            .collect();
                        raw_inside.push(line);
                    }
                    let all_inside = raw_inside.join("\n");
                    let kind = marker_re
                        .captures(&all_inside)
                        .and_then(|caps| caps.get(1))
                        .map(|m| match m.as_str() {
                            "d" => ShapeKind::Document,
                            "s" => ShapeKind::Storage,
                            "o" => ShapeKind::Ellipse,
                            "mo" => ShapeKind::ManualOperation,
                            "c" => ShapeKind::Decision,
                            "tr" => ShapeKind::Trapezoid,
                            "io" => ShapeKind::Io,
                            _ => ShapeKind::Rect,
                        })
                        .unwrap_or(ShapeKind::Rect);

                    let fill = color_re
                        .captures(&all_inside)
                        .and_then(|caps| caps.get(1))
                        .map(|caps| named_color(caps.as_str()))
                        .unwrap_or(Color::rgb(255, 255, 255));
                    let text_color = if fill.luminance() < 110.0 {
                        Color::rgb(255, 255, 255)
                    } else {
                        Color::rgb(0, 0, 0)
                    };
                    let rounded = options.round_corners
                        || (kind == ShapeKind::Rect && tl == '/' && tr == '\\' && bl == '\\' && br == '/');

                    let mut text_lines = Vec::new();
                    for line in raw_inside {
                        let line = marker_re.replace_all(&line, "");
                        let line = color_re.replace_all(&line, "");
                        let trimmed = line.trim();
                        if trimmed.is_empty() {
                            continue;
                        }
                        if let Some(rest) = trimmed.strip_prefix("o ") {
                            text_lines.push(TextLine {
                                text: rest.trim().to_string(),
                                bullet: true,
                            });
                        } else {
                            text_lines.push(TextLine {
                                text: trimmed.to_string(),
                                bullet: false,
                            });
                        }
                    }

                    for y in (y0 + 1)..y1 {
                        for x in (x0 + 1)..x1 {
                            interior_mask[y as usize][x as usize] = true;
                        }
                    }
                    for x in x0..x1 {
                        boundary_edges.insert(Edge::new(Point { x, y: y0 }, Point { x: x + 1, y: y0 }));
                        boundary_edges.insert(Edge::new(Point { x, y: y1 }, Point { x: x + 1, y: y1 }));
                    }
                    for y in y0..y1 {
                        boundary_edges.insert(Edge::new(Point { x: x0, y }, Point { x: x0, y: y + 1 }));
                        boundary_edges.insert(Edge::new(Point { x: x1, y }, Point { x: x1, y: y + 1 }));
                    }

                    shapes.push(Shape {
                        x0,
                        y0,
                        x1,
                        y1,
                        kind,
                        rounded,
                        fill,
                        text_color,
                        text_lines,
                    });
                }
            }
        }
    }

    shapes.sort_by_key(|shape| {
        let area = (shape.x1 - shape.x0) * (shape.y1 - shape.y0);
        -area
    });

    let separations = if options.no_separation {
        Vec::new()
    } else {
        compute_separations(&shapes)
    };

    let mut edge_dashed = HashMap::new();
    let mut adjacency: HashMap<Point, Vec<Point>> = HashMap::new();
    let mut markers = Vec::new();

    for y in 0..height as i32 {
        for x in 0..width as i32 {
            let point = Point { x, y };
            let ch = grid[y as usize][x as usize];
            if ch == '*' {
                markers.push(point);
            }
            for dir in actual_dirs(&grid, x, y) {
                let next = step(point, dir);
                if next.x < 0 || next.y < 0 || next.x >= width as i32 || next.y >= height as i32 {
                    continue;
                }
                let edge = Edge::new(point, next);
                if boundary_edges.contains(&edge) {
                    continue;
                }
                adjacency.entry(point).or_default().push(next);
                adjacency.entry(next).or_default().push(point);
                let dashed = matches!(ch, '=' | ':')
                    || matches!(grid[next.y as usize][next.x as usize], '=' | ':');
                edge_dashed
                    .entry(edge)
                    .and_modify(|value| *value |= dashed)
                    .or_insert(dashed);
            }
        }
    }

    for neighbors in adjacency.values_mut() {
        neighbors.sort_by_key(|point| (point.x, point.y));
        neighbors.dedup();
    }

    let paths = trace_paths(&grid, &adjacency, &edge_dashed);
    let loose_text = find_loose_text(&grid, &interior_mask);

    Diagram {
        width,
        height,
        shapes,
        paths,
        markers,
        loose_text,
        separations,
    }
}

fn is_horizontal_edge(ch: char) -> bool {
    matches!(ch, '-' | '=' | '+')
}

fn is_vertical_edge(ch: char) -> bool {
    matches!(ch, '|' | ':' | '+')
}

fn named_color(name: &str) -> Color {
    match name {
        "RED" => Color::rgb(224, 48, 32),
        "GRE" => Color::rgb(144, 208, 144),
        "BLU" => Color::rgb(80, 80, 176),
        "PNK" => Color::rgb(240, 160, 160),
        "YEL" => Color::rgb(240, 240, 48),
        "BLK" => Color::rgb(0, 0, 0),
        _ => Color::rgb(255, 255, 255),
    }
}

fn compute_separations(shapes: &[Shape]) -> Vec<Separation> {
    let mut out = Vec::new();
    for i in 0..shapes.len() {
        for j in (i + 1)..shapes.len() {
            let a = &shapes[i];
            let b = &shapes[j];
            if a.x1 == b.x0 || b.x1 == a.x0 {
                let coord = if a.x1 == b.x0 { a.x1 } else { b.x1 };
                let start = max(a.y0, b.y0);
                let end = min(a.y1, b.y1);
                if end - start >= 1 {
                    out.push(Separation {
                        vertical: true,
                        coord,
                        start,
                        end,
                    });
                }
            }
            if a.y1 == b.y0 || b.y1 == a.y0 {
                let coord = if a.y1 == b.y0 { a.y1 } else { b.y1 };
                let start = max(a.x0, b.x0);
                let end = min(a.x1, b.x1);
                if end - start >= 1 {
                    out.push(Separation {
                        vertical: false,
                        coord,
                        start,
                        end,
                    });
                }
            }
        }
    }
    out
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Dir {
    Left,
    Right,
    Up,
    Down,
}

fn step(point: Point, dir: Dir) -> Point {
    match dir {
        Dir::Left => Point {
            x: point.x - 1,
            y: point.y,
        },
        Dir::Right => Point {
            x: point.x + 1,
            y: point.y,
        },
        Dir::Up => Point {
            x: point.x,
            y: point.y - 1,
        },
        Dir::Down => Point {
            x: point.x,
            y: point.y + 1,
        },
    }
}

fn opposite(dir: Dir) -> Dir {
    match dir {
        Dir::Left => Dir::Right,
        Dir::Right => Dir::Left,
        Dir::Up => Dir::Down,
        Dir::Down => Dir::Up,
    }
}

fn base_can(ch: char, dir: Dir) -> bool {
    match ch {
        '-' | '=' => matches!(dir, Dir::Left | Dir::Right),
        '|' | ':' => matches!(dir, Dir::Up | Dir::Down),
        '+' | '*' => true,
        '<' => dir == Dir::Right,
        '>' => dir == Dir::Left,
        '^' => dir == Dir::Down,
        'v' | 'V' => dir == Dir::Up,
        '/' | '\\' => true,
        _ => false,
    }
}

fn actual_dirs(grid: &[Vec<char>], x: i32, y: i32) -> Vec<Dir> {
    let width = grid.first().map_or(0, Vec::len) as i32;
    let height = grid.len() as i32;
    if x < 0 || y < 0 || x >= width || y >= height {
        return Vec::new();
    }
    let ch = grid[y as usize][x as usize];
    let mut available = Vec::new();
    for dir in [Dir::Left, Dir::Right, Dir::Up, Dir::Down] {
        if !base_can(ch, dir) {
            continue;
        }
        let next = step(Point { x, y }, dir);
        if next.x < 0 || next.y < 0 || next.x >= width || next.y >= height {
            continue;
        }
        let other = grid[next.y as usize][next.x as usize];
        if base_can(other, opposite(dir)) {
            available.push(dir);
        }
    }
    if ch == '/' {
        let has = |dir| available.contains(&dir);
        for pair in [
            [Dir::Right, Dir::Down],
            [Dir::Left, Dir::Up],
            [Dir::Right, Dir::Up],
            [Dir::Left, Dir::Down],
        ] {
            if has(pair[0]) && has(pair[1]) {
                return vec![pair[0], pair[1]];
            }
        }
    }
    if ch == '\\' {
        let has = |dir| available.contains(&dir);
        for pair in [
            [Dir::Left, Dir::Down],
            [Dir::Right, Dir::Up],
            [Dir::Left, Dir::Up],
            [Dir::Right, Dir::Down],
        ] {
            if has(pair[0]) && has(pair[1]) {
                return vec![pair[0], pair[1]];
            }
        }
    }
    available
}

fn trace_paths(
    grid: &[Vec<char>],
    adjacency: &HashMap<Point, Vec<Point>>,
    edge_dashed: &HashMap<Edge, bool>,
) -> Vec<StrokePath> {
    let mut remaining: HashSet<Edge> = edge_dashed.keys().copied().collect();
    let mut paths = Vec::new();

    let mut start_nodes: Vec<Point> = adjacency
        .iter()
        .filter_map(|(point, neighbors)| {
            if neighbors.len() != 2 {
                Some(*point)
            } else {
                None
            }
        })
        .collect();
    start_nodes.sort_by_key(|point| (point.y, point.x));

    for start in start_nodes {
        if let Some(neighbors) = adjacency.get(&start) {
            for &next in neighbors {
                let edge = Edge::new(start, next);
                if !remaining.contains(&edge) {
                    continue;
                }
                paths.push(trace_one_path(grid, adjacency, edge_dashed, &mut remaining, start, next));
            }
        }
    }

    while let Some(edge) = remaining.iter().next().copied() {
        paths.push(trace_one_path(
            grid,
            adjacency,
            edge_dashed,
            &mut remaining,
            edge.a,
            edge.b,
        ));
    }

    paths
}

fn trace_one_path(
    grid: &[Vec<char>],
    adjacency: &HashMap<Point, Vec<Point>>,
    edge_dashed: &HashMap<Edge, bool>,
    remaining: &mut HashSet<Edge>,
    start: Point,
    next: Point,
) -> StrokePath {
    let mut points = vec![start];
    let mut dashed = false;
    let mut prev = start;
    let mut curr = next;
    let arrow_start = arrow_for(grid, start, next);
    loop {
        let edge = Edge::new(prev, curr);
        remaining.remove(&edge);
        dashed |= edge_dashed.get(&edge).copied().unwrap_or(false);
        points.push(curr);
        let neighbors = adjacency.get(&curr).cloned().unwrap_or_default();
        let candidates: Vec<Point> = neighbors
            .into_iter()
            .filter(|point| *point != prev && remaining.contains(&Edge::new(curr, *point)))
            .collect();
        if candidates.len() != 1 {
            break;
        }
        prev = curr;
        curr = candidates[0];
        if curr == start {
            let edge = Edge::new(prev, curr);
            remaining.remove(&edge);
            dashed |= edge_dashed.get(&edge).copied().unwrap_or(false);
            points.push(curr);
            break;
        }
    }
    let arrow_end = if points.len() >= 2 {
        let last = *points.last().unwrap();
        let before = points[points.len() - 2];
        arrow_for(grid, last, before)
    } else {
        None
    };
    StrokePath {
        points,
        dashed,
        arrow_start,
        arrow_end,
    }
}

fn arrow_for(grid: &[Vec<char>], point: Point, other: Point) -> Option<ArrowDir> {
    let ch = grid
        .get(point.y as usize)
        .and_then(|row| row.get(point.x as usize))
        .copied()
        .unwrap_or(' ');
    match ch {
        '>' if other.x < point.x => Some(ArrowDir::Right),
        '<' if other.x > point.x => Some(ArrowDir::Left),
        '^' if other.y > point.y => Some(ArrowDir::Up),
        'v' | 'V' if other.y < point.y => Some(ArrowDir::Down),
        _ => None,
    }
}

fn find_loose_text(grid: &[Vec<char>], interior_mask: &[Vec<bool>]) -> Vec<LooseText> {
    let mut out = Vec::new();
    for (y, row) in grid.iter().enumerate() {
        let mut x = 0usize;
        while x < row.len() {
            if interior_mask[y][x] || is_line_char(row[x]) {
                x += 1;
                continue;
            }
            let start = x;
            let mut raw = String::new();
            while x < row.len() && !interior_mask[y][x] && !is_line_char(row[x]) {
                raw.push(row[x]);
                x += 1;
            }
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                continue;
            }
            let lead = raw.find(trimmed).unwrap_or(0);
            let run_start = start + lead;
            let run_end = run_start + trimmed.chars().count();
            out.push(LooseText {
                row: y as i32,
                start: run_start as i32,
                end: run_end as i32,
                text: trimmed.to_string(),
            });
        }
    }
    out
}

fn is_line_char(ch: char) -> bool {
    matches!(
        ch,
        ' ' | '-' | '=' | '|' | ':' | '+' | '/' | '\\' | '<' | '>' | '^' | 'v' | 'V' | '*'
    )
}

fn render_svg(diagram: &Diagram, options: &CliOptions, for_png: bool) -> String {
    let width = (((diagram.width as f32) + 4.0) * CELL_W * options.scale).round() as i32;
    let height = (((diagram.height as f32) + 4.0) * CELL_H * options.scale).round() as i32;

    let mut out = String::new();
    writeln!(
        out,
        "<?xml version='1.0' encoding='UTF-8' standalone='no'?>"
    )
    .unwrap();
    writeln!(out, "<svg ").unwrap();
    writeln!(out, "    xmlns='http://www.w3.org/2000/svg'").unwrap();
    writeln!(out, "    width='{}'", width).unwrap();
    writeln!(out, "    height='{}'", height).unwrap();
    if for_png && options.no_antialias {
        writeln!(out, "    shape-rendering='crispEdges'").unwrap();
    } else {
        writeln!(out, "    shape-rendering='geometricPrecision'").unwrap();
    }
    writeln!(out, "    version='1.0'>").unwrap();
    writeln!(out, "  <defs>").unwrap();
    if let Some(url) = &options.svg_font_url {
        writeln!(out, "    <style type='text/css'>").unwrap();
        writeln!(out, "      @font-face {{").unwrap();
        writeln!(out, "        font-family: Custom;").unwrap();
        writeln!(out, "        src: url('{}');", escape_attr(url)).unwrap();
        writeln!(out, "      }}").unwrap();
        writeln!(out, "    </style>").unwrap();
    }
    writeln!(out, "    <filter id='f2' x='0' y='0' width='200%' height='200%'>").unwrap();
    writeln!(
        out,
        "      <feOffset result='offOut' in='SourceGraphic' dx='5' dy='5' />"
    )
    .unwrap();
    writeln!(
        out,
        "      <feGaussianBlur result='blurOut' in='offOut' stdDeviation='3' />"
    )
    .unwrap();
    writeln!(
        out,
        "      <feBlend in='SourceGraphic' in2='blurOut' mode='normal' />"
    )
    .unwrap();
    writeln!(out, "    </filter>").unwrap();
    writeln!(out, "  </defs>").unwrap();
    writeln!(
        out,
        "  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round'>"
    )
    .unwrap();

    if !options.transparent {
        let bg = options.background;
        if for_png && bg.a < 255 {
            writeln!(
                out,
                "    <rect x='0' y='0' width='{}' height='{}' style='fill: {}; fill-opacity: {:.3}'/>",
                width,
                height,
                bg.hex_rgb(),
                bg.a as f32 / 255.0
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "    <rect x='0' y='0' width='{}' height='{}' style='fill: {}'/>",
                width,
                height,
                bg.hex_rgb()
            )
            .unwrap();
        }
    }

    if options.debug {
        render_debug_grid(&mut out, width as f32, height as f32, options.scale);
    }

    for shape in &diagram.shapes {
        if options.no_shadows {
            continue;
        }
        render_shape_shadow(&mut out, shape, options);
    }

    for sep in &diagram.separations {
        render_separation(&mut out, sep, options);
    }

    for shape in &diagram.shapes {
        render_shape(&mut out, shape, options);
    }

    for path in &diagram.paths {
        render_path(&mut out, path, options);
    }

    for marker in &diagram.markers {
        render_marker(&mut out, *marker, options);
    }

    for shape in &diagram.shapes {
        render_shape_text(&mut out, shape, options);
    }
    for text in &diagram.loose_text {
        render_loose_text(&mut out, text, options);
    }

    writeln!(out, "  </g>").unwrap();
    writeln!(out, "</svg>").unwrap();
    out
}

fn render_debug_grid(out: &mut String, width: f32, height: f32, scale: f32) {
    let step_x = CELL_W * scale;
    let step_y = CELL_H * scale;
    let mut x = 0.0;
    while x <= width {
        writeln!(
            out,
            "    <path stroke='#666666' stroke-width='0.5' fill='none' d='M{:.1} 0 L{:.1} {:.1}' />",
            x, x, height
        )
        .unwrap();
        x += step_x;
    }
    let mut y = 0.0;
    while y <= height {
        writeln!(
            out,
            "    <path stroke='#666666' stroke-width='0.5' fill='none' d='M0 {:.1} L{:.1} {:.1}' />",
            y, width, y
        )
        .unwrap();
        y += step_y;
    }
}

fn render_shape_shadow(out: &mut String, shape: &Shape, options: &CliOptions) {
    let path = shape_path(shape, options);
    if shape.kind == ShapeKind::Storage {
        writeln!(
            out,
            "    <path stroke='gray' fill='gray' filter='url(#f2)' d='{}' />",
            path
        )
        .unwrap();
    } else {
        writeln!(
            out,
            "    <path stroke='gray' fill='gray' filter='url(#f2)' d='{}' />",
            path
        )
        .unwrap();
    }
}

fn render_shape(out: &mut String, shape: &Shape, options: &CliOptions) {
    let path = shape_path(shape, options);
    if shape.kind == ShapeKind::Storage {
        writeln!(
            out,
            "    <path stroke='white' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='{}' d='{}' />",
            shape.fill.hex_rgb(),
            path
        )
        .unwrap();
        writeln!(
            out,
            "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='none' d='{}' />",
            path
        )
        .unwrap();
        return;
    }
    writeln!(
        out,
        "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='{}' d='{}' />",
        shape.fill.hex_rgb(),
        path
    )
    .unwrap();
}

fn render_separation(out: &mut String, separation: &Separation, options: &CliOptions) {
    if separation.vertical {
        let x = px_x(separation.coord, options.scale);
        let y0 = px_y(separation.start, options.scale);
        let y1 = px_y(separation.end, options.scale);
        writeln!(
            out,
            "    <path stroke='#ffffff' stroke-width='{:.1}' stroke-linecap='square' fill='none' d='M{:.1} {:.1} L{:.1} {:.1}' />",
            3.0 * options.scale,
            x,
            y0,
            x,
            y1
        )
        .unwrap();
    } else {
        let y = px_y(separation.coord, options.scale);
        let x0 = px_x(separation.start, options.scale);
        let x1 = px_x(separation.end, options.scale);
        writeln!(
            out,
            "    <path stroke='#ffffff' stroke-width='{:.1}' stroke-linecap='square' fill='none' d='M{:.1} {:.1} L{:.1} {:.1}' />",
            3.0 * options.scale,
            x0,
            y,
            x1,
            y
        )
        .unwrap();
    }
}

fn render_path(out: &mut String, path: &StrokePath, options: &CliOptions) {
    if path.points.len() < 2 {
        return;
    }
    let mut d = String::new();
    for (index, point) in path.points.iter().enumerate() {
        let x = px_x(point.x, options.scale);
        let y = px_y(point.y, options.scale);
        if index == 0 {
            write!(d, "M{:.1} {:.1} ", x, y).unwrap();
        } else {
            write!(d, "L{:.1} {:.1} ", x, y).unwrap();
        }
    }
    if path.dashed {
        writeln!(
            out,
            "    <path stroke='#000000' stroke-width='1.0' stroke-dasharray='5.0,5.0' stroke-miterlimit='0' stroke-linecap='butt' stroke-linejoin='round' fill='none' d='{}' />",
            d
        )
        .unwrap();
    } else {
        writeln!(
            out,
            "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='none' d='{}' />",
            d
        )
        .unwrap();
    }
    if let Some(dir) = path.arrow_start {
        render_arrow(out, path.points[0], dir, options);
    }
    if let Some(dir) = path.arrow_end {
        render_arrow(out, *path.points.last().unwrap(), dir, options);
    }
}

fn render_arrow(out: &mut String, point: Point, dir: ArrowDir, options: &CliOptions) {
    let x = px_x(point.x, options.scale);
    let y = px_y(point.y, options.scale);
    let (a, b, c) = match dir {
        ArrowDir::Right => (
            (x + 5.0 * options.scale, y),
            (x - 5.0 * options.scale, y - 7.0 * options.scale),
            (x - 5.0 * options.scale, y + 7.0 * options.scale),
        ),
        ArrowDir::Left => (
            (x - 5.0 * options.scale, y),
            (x + 5.0 * options.scale, y - 7.0 * options.scale),
            (x + 5.0 * options.scale, y + 7.0 * options.scale),
        ),
        ArrowDir::Up => (
            (x, y - 7.0 * options.scale),
            (x - 5.0 * options.scale, y + 7.0 * options.scale),
            (x + 5.0 * options.scale, y + 7.0 * options.scale),
        ),
        ArrowDir::Down => (
            (x, y + 7.0 * options.scale),
            (x - 5.0 * options.scale, y - 7.0 * options.scale),
            (x + 5.0 * options.scale, y - 7.0 * options.scale),
        ),
    };
    writeln!(
        out,
        "    <path stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z' />",
        a.0, a.1, b.0, b.1, c.0, c.1
    )
    .unwrap();
}

fn render_marker(out: &mut String, point: Point, options: &CliOptions) {
    let x = px_x(point.x, options.scale);
    let y = px_y(point.y, options.scale);
    let r = 4.0 * options.scale;
    writeln!(
        out,
        "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='white' d='M{:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} z' />",
        x,
        y - r,
        x + r * 0.5523,
        y - r,
        x + r,
        y - r * 0.5523,
        x + r,
        y,
        x + r,
        y + r * 0.5523,
        x + r * 0.5523,
        y + r,
        x,
        y + r,
        x - r * 0.5523,
        y + r,
        x - r,
        y + r * 0.5523,
        x - r,
        y,
        x - r,
        y - r * 0.5523,
        x - r * 0.5523,
        y - r,
        x,
        y - r
    )
    .unwrap();
}

fn render_shape_text(out: &mut String, shape: &Shape, options: &CliOptions) {
    if shape.text_lines.is_empty() {
        return;
    }
    let left = px_x(shape.x0, options.scale);
    let right = px_x(shape.x1, options.scale);
    let top = px_y(shape.y0, options.scale);
    let bottom = px_y(shape.y1, options.scale);
    let text_width = (right - left - 16.0 * options.scale).max(16.0 * options.scale);
    let line_height = 16.0 * options.scale;
    let total_height = (shape.text_lines.len().saturating_sub(1) as f32) * line_height;
    let center_x = (left + right) / 2.0;
    let start_y = (top + bottom) / 2.0 - total_height / 2.0;
    let font_family = if options.svg_font_url.is_some() {
        "Custom"
    } else {
        "Courier"
    };

    for (index, line) in shape.text_lines.iter().enumerate() {
        let y = start_y + index as f32 * line_height;
        let font_size = fit_font_size(&line.text, text_width, BASE_FONT_SIZE * options.scale);
        if line.bullet {
            let bullet_x = left + 18.0 * options.scale;
            let text_x = left + 28.0 * options.scale;
            let r = 3.0 * options.scale;
            writeln!(
                out,
                "    <path stroke='none' fill='{}' d='M{:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} z' />",
                shape.text_color.hex_rgb(),
                bullet_x,
                y - r,
                bullet_x + r * 0.5523,
                y - r,
                bullet_x + r,
                y - r * 0.5523,
                bullet_x + r,
                y,
                bullet_x + r,
                y + r * 0.5523,
                bullet_x + r * 0.5523,
                y + r,
                bullet_x,
                y + r,
                bullet_x - r * 0.5523,
                y + r,
                bullet_x - r,
                y + r * 0.5523,
                bullet_x - r,
                y,
                bullet_x - r,
                y - r * 0.5523,
                bullet_x - r * 0.5523,
                y - r,
                bullet_x,
                y - r
            )
            .unwrap();
            writeln!(
                out,
                "    <text x='{:.1}' y='{:.1}' font-family='{}' font-size='{:.0}' stroke='none' fill='{}' dominant-baseline='middle'>{}</text>",
                text_x,
                y,
                font_family,
                font_size,
                shape.text_color.hex_rgb(),
                cdata_text(&line.text)
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "    <text x='{:.1}' y='{:.1}' font-family='{}' font-size='{:.0}' stroke='none' fill='{}' text-anchor='middle' dominant-baseline='middle'>{}</text>",
                center_x,
                y,
                font_family,
                font_size,
                shape.text_color.hex_rgb(),
                cdata_text(&line.text)
            )
            .unwrap();
        }
    }
}

fn render_loose_text(out: &mut String, text: &LooseText, options: &CliOptions) {
    let left = px_x(text.start, options.scale);
    let right = px_x(text.end, options.scale);
    let x = (left + right) / 2.0;
    let y = px_y(text.row, options.scale);
    let max_width = (right - left).max(20.0 * options.scale);
    let font_size = fit_font_size(&text.text, max_width, BASE_FONT_SIZE * options.scale);
    let font_family = if options.svg_font_url.is_some() {
        "Custom"
    } else {
        "Courier"
    };
    writeln!(
        out,
        "    <text x='{:.1}' y='{:.1}' font-family='{}' font-size='{:.0}' stroke='none' fill='#000000' text-anchor='middle' dominant-baseline='middle'>{}</text>",
        x,
        y,
        font_family,
        font_size,
        cdata_text(&text.text)
    )
    .unwrap();
}

fn fit_font_size(text: &str, max_width: f32, base: f32) -> f32 {
    let estimate = text.chars().count() as f32 * base * 0.62;
    if estimate <= max_width {
        base
    } else {
        (base * max_width / estimate).floor().max(10.0 * (base / BASE_FONT_SIZE))
    }
}

fn cdata_text(text: &str) -> String {
    format!("<![CDATA[{}]]>", text.replace("]]>", "]]]]><![CDATA[>"))
}

fn escape_attr(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('\'', "&apos;")
        .replace('"', "&quot;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

fn px_x(x: i32, scale: f32) -> f32 {
    (x as f32 + PAD_X) * CELL_W * scale
}

fn px_y(y: i32, scale: f32) -> f32 {
    (y as f32 + PAD_Y) * CELL_H * scale
}

fn shape_path(shape: &Shape, options: &CliOptions) -> String {
    let x0 = px_x(shape.x0, options.scale);
    let y0 = px_y(shape.y0, options.scale);
    let x1 = px_x(shape.x1, options.scale);
    let y1 = px_y(shape.y1, options.scale);
    let cx = (x0 + x1) / 2.0;
    let cy = (y0 + y1) / 2.0;
    let width = x1 - x0;
    let height = y1 - y0;

    match shape.kind {
        ShapeKind::Rect => {
            if shape.rounded {
                let r = 5.0 * options.scale;
                format!(
                    "M{:.1} {:.1} L{:.1} {:.1} Q{:.1} {:.1} {:.1} {:.1} L{:.1} {:.1} Q{:.1} {:.1} {:.1} {:.1} L{:.1} {:.1} Q{:.1} {:.1} {:.1} {:.1} L{:.1} {:.1} Q{:.1} {:.1} {:.1} {:.1} z",
                    x0 + r,
                    y0,
                    x1 - r,
                    y0,
                    x1,
                    y0,
                    x1,
                    y0 + r,
                    x1,
                    y1 - r,
                    x1,
                    y1,
                    x1 - r,
                    y1,
                    x0 + r,
                    y1,
                    x0,
                    y1,
                    x0,
                    y1 - r,
                    x0,
                    y0 + r,
                    x0,
                    y0,
                    x0 + r,
                    y0
                )
            } else {
                format!(
                    "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z",
                    x0, y0, x1, y0, x1, y1, x0, y1
                )
            }
        }
        ShapeKind::Document => {
            let dx = width / 6.0;
            let wave = 8.0 * options.scale;
            format!(
                "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} Q{:.1} {:.1} {:.1} {:.1} Q{:.1} {:.1} {:.1} {:.1} z",
                x0,
                y0,
                x1,
                y0,
                x1,
                y1,
                cx + dx,
                y1 - wave,
                cx,
                y1,
                cx - dx,
                y1 + wave,
                x0,
                y1
            )
        }
        ShapeKind::Storage => {
            let top = 7.0 * options.scale;
            let bottom = 10.0 * options.scale;
            let inset = width / 6.0;
            format!(
                "M{:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} M{:.1} {:.1} L{:.1} {:.1} C{:.1} {:.1} {:.1} {:.1} {:.1} {:.1} L{:.1} {:.1} ",
                x0,
                y0,
                x0 + inset,
                y0 + top,
                x1 - inset,
                y0 + top,
                x1,
                y0,
                x1 - inset,
                y0 - top,
                x0 + inset,
                y0 - top,
                x0,
                y0,
                x0,
                y0,
                x0,
                y1,
                x0 + inset,
                y1 + bottom,
                x1 - inset,
                y1 + bottom,
                x1,
                y1,
                x1,
                y0
            )
        }
        ShapeKind::Ellipse => {
            let rx = width / 2.0;
            let ry = height / 2.0;
            let k = 0.5522847;
            format!(
                "M{:.1} {:.1} C{:.5} {:.1} {:.1} {:.5} {:.1} {:.1} C{:.1} {:.5} {:.5} {:.1} {:.1} {:.1} C{:.5} {:.1} {:.1} {:.5} {:.1} {:.1} C{:.1} {:.5} {:.5} {:.1} {:.1} {:.1} z",
                cx,
                y0,
                cx + rx * k,
                y0,
                x1,
                cy - ry * k,
                x1,
                cy,
                x1,
                cy + ry * k,
                cx + rx * k,
                y1,
                cx,
                y1,
                cx - rx * k,
                y1,
                x0,
                cy + ry * k,
                x0,
                cy,
                x0,
                cy - ry * k,
                cx - rx * k,
                y0,
                cx,
                y0
            )
        }
        ShapeKind::ManualOperation => {
            let slope = if options.fixed_slope {
                10.0 * options.scale
            } else {
                10.0 * options.scale
            };
            format!(
                "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z",
                x0 - slope / 2.0,
                y0,
                x1 + slope / 2.0,
                y0,
                x1 - slope / 2.0,
                y1,
                x0 + slope / 2.0,
                y1
            )
        }
        ShapeKind::Decision => {
            format!(
                "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z",
                x0, cy, cx, y0, x1, cy, cx, y1
            )
        }
        ShapeKind::Trapezoid => {
            let slope = if options.fixed_slope {
                10.0 * options.scale
            } else {
                10.0 * options.scale
            };
            format!(
                "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z",
                x0 + slope / 2.0,
                y0,
                x1 - slope / 2.0,
                y0,
                x1 + slope / 2.0,
                y1,
                x0 - slope / 2.0,
                y1
            )
        }
        ShapeKind::Io => {
            let slope = if options.fixed_slope {
                10.0 * options.scale
            } else {
                10.0 * options.scale
            };
            format!(
                "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z",
                x0 + slope / 2.0,
                y0,
                x1 + slope / 2.0,
                y0,
                x1 - slope / 2.0,
                y1,
                x0 - slope / 2.0,
                y1
            )
        }
    }
}

fn render_png(svg: &str, output: &Path) -> Result<()> {
    let mut opt = usvg::Options::default();
    opt.font_family = "DejaVu Sans Mono".to_string();
    let mut fontdb = usvg::fontdb::Database::new();
    fontdb.load_system_fonts();
    let tree = usvg::Tree::from_str(svg, &opt, &fontdb)
        .map_err(|err| anyhow!("parsing svg for png render: {err}"))?;
    let size = tree.size().to_int_size();
    let mut pixmap = tiny_skia::Pixmap::new(size.width(), size.height())
        .ok_or_else(|| anyhow!("allocating pixmap"))?;
    let mut pixmap_mut = pixmap.as_mut();
    resvg::render(&tree, tiny_skia::Transform::default(), &mut pixmap_mut);
    pixmap
        .save_png(output)
        .with_context(|| format!("writing {}", output.display()))?;
    Ok(())
}

