                y0,
                x0 + inset,
                y0 + top,
                x1 - inset,
                y0 + top,
                x1,
                y0,
                x1 - inset,
                y0 - top,
                x0 + inset,
                y0 - top,
                x0,
                y0,
                x0,
                y0,
                x0,
                y1,
                x0 + inset,
                y1 + bottom,
                x1 - inset,
                y1 + bottom,
                x1,
                y1,
                x1,
                y0
            )
        }
        ShapeKind::Ellipse => {
            let rx = width / 2.0;
            let ry = height / 2.0;
            let k = 0.5522847;
            format!(
                "M{:.1} {:.1} C{:.5} {:.1} {:.1} {:.5} {:.1} {:.1} C{:.1} {:.5} {:.5} {:.1} {:.1} {:.1} C{:.5} {:.1} {:.1} {:.5} {:.1} {:.1} C{:.1} {:.5} {:.5} {:.1} {:.1} {:.1} z",
                cx,
                y0,
                cx + rx * k,
                y0,
                x1,
                cy - ry * k,
                x1,
                cy,
                x1,
                cy + ry * k,
                cx + rx * k,
                y1,
                cx,
                y1,
                cx - rx * k,
                y1,
                x0,
                cy + ry * k,
                x0,
                cy,
                x0,
                cy - ry * k,
                cx - rx * k,
                y0,
                cx,
                y0
            )
        }
        ShapeKind::ManualOperation => {
            let slope = if options.fixed_slope {
                10.0 * options.scale
            } else {
                10.0 * options.scale
            };
            format!(
                "M{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} L{:.1} {:.1} z",
                x0 - slope / 2.0,
                y0,
                x1 + slope / 2.0,
                y0,
                x1 - slope / 2.0,
                y1,
                x0 + slope / 2.0,
                y1
            )
        }
        ShapeKind::Decision => {
            format!(
