+    private static Diagram buildDiagram(List<String> lines, CliOptions options) {
+        int width = 0;
+        for (String line : lines) {
+            width = Math.max(width, line.length());
+        }
+        int height = lines.size();
+        char[][] grid = new char[height][width];
+        for (int y = 0; y < height; y++) {
+            String line = lines.get(y);
+            for (int x = 0; x < width; x++) {
+                grid[y][x] = x < line.length() ? line.charAt(x) : ' ';
+            }
+        }
+
+        boolean[][] interiorMask = new boolean[height][width];
+        Set<GridEdge> boundaryEdges = new HashSet<>();
+        Set<String> seen = new HashSet<>();
+        List<DiagramShape> shapes = new ArrayList<>();
+
+        for (int y0 = 0; y0 < height; y0++) {
+            for (int x0 = 0; x0 < width; x0++) {
+                char tl = grid[y0][x0];
+                if (!(tl == '+' || tl == '/')) {
+                    continue;
+                }
+                for (int x1 = x0 + 2; x1 < width; x1++) {
+                    char tr = grid[y0][x1];
+                    if (!(tr == '+' || tr == '\\')) {
+                        continue;
+                    }
+                    boolean ok = true;
+                    for (int x = x0 + 1; x < x1; x++) {
+                        if (!isHorizontalEdge(grid[y0][x])) {
+                            ok = false;
+                            break;
+                        }
+                    }
+                    if (!ok) {
+                        continue;
+                    }
+                    for (int y1 = y0 + 2; y1 < height; y1++) {
+                        char bl = grid[y1][x0];
+                        char br = grid[y1][x1];
+                        if (!((bl == '+' || bl == '\\') && (br == '+' || br == '/'))) {
+                            continue;
+                        }
+                        ok = true;
+                        for (int x = x0 + 1; x < x1; x++) {
+                            if (!isHorizontalEdge(grid[y1][x])) {
+                                ok = false;
+                                break;
+                            }
+                        }
+                        if (!ok) {
+                            continue;
+                        }
+                        for (int y = y0 + 1; y < y1; y++) {
+                            if (!isVerticalEdge(grid[y][x0]) || !isVerticalEdge(grid[y][x1])) {
+                                ok = false;
+                                break;
+                            }
+                        }
+                        if (!ok) {
+                            continue;
+                        }
+                        String key = x0 + ":" + y0 + ":" + x1 + ":" + y1;
+                        if (!seen.add(key)) {
+                            continue;
+                        }
+
+                        List<String> inside = new ArrayList<>();
+                        StringBuilder allInside = new StringBuilder();
+                        for (int y = y0 + 1; y < y1; y++) {
+                            String line = new String(grid[y], x0 + 1, x1 - x0 - 1);
+                            inside.add(line);
+                            if (allInside.length() > 0) {
+                                allInside.append('\n');
+                            }
+                            allInside.append(line);
+                        }
+                        ShapeKind kind = detectShapeKind(allInside.toString());
+                        RgbaColor fill = detectFillColor(allInside.toString());
+                        RgbaColor textColor = fill.luminance() < 110.0
+                                ? new RgbaColor(255, 255, 255, 255)
+                                : new RgbaColor(0, 0, 0, 255);
+                        boolean rounded = options.roundCorners
+                                || (kind == ShapeKind.RECT
+                                        && tl == '/'
+                                        && tr == '\\'
+                                        && bl == '\\'
+                                        && br == '/');
+
+                        List<TextEntry> textLines = new ArrayList<>();
+                        for (String line : inside) {
+                            String cleaned = COLOR_PATTERN.matcher(MARKER_PATTERN.matcher(line).replaceAll(""))
+                                    .replaceAll("");
+                            String trimmed = cleaned.trim();
+                            if (trimmed.isEmpty()) {
+                                continue;
+                            }
+                            if (trimmed.startsWith("o ")) {
+                                textLines.add(new TextEntry(trimmed.substring(2).trim(), true));
+                            } else {
+                                textLines.add(new TextEntry(trimmed, false));
+                            }
+                        }
+
+                        for (int y = y0 + 1; y < y1; y++) {
+                            for (int x = x0 + 1; x < x1; x++) {
+                                interiorMask[y][x] = true;
+                            }
+                        }
+                        for (int x = x0; x < x1; x++) {
+                            boundaryEdges.add(new GridEdge(new GridPoint(x, y0), new GridPoint(x + 1, y0)));
+                            boundaryEdges.add(new GridEdge(new GridPoint(x, y1), new GridPoint(x + 1, y1)));
+                        }
+                        for (int y = y0; y < y1; y++) {
+                            boundaryEdges.add(new GridEdge(new GridPoint(x0, y), new GridPoint(x0, y + 1)));
+                            boundaryEdges.add(new GridEdge(new GridPoint(x1, y), new GridPoint(x1, y + 1)));
+                        }
+
+                        shapes.add(new DiagramShape(x0, y0, x1, y1, kind, rounded, fill, textColor, textLines));
+                    }
+                }
+            }
+        }
+
+        shapes.sort((a, b) -> Integer.compare((b.x1 - b.x0) * (b.y1 - b.y0), (a.x1 - a.x0) * (a.y1 - a.y0)));
+
+        List<Separation> separations = options.noSeparation ? new ArrayList<>() : computeSeparations(shapes);
+        Map<GridPoint, List<GridPoint>> adjacency = new HashMap<>();
+        Map<GridEdge, Boolean> dashedEdges = new HashMap<>();
+        List<GridPoint> markers = new ArrayList<>();
+
+        for (int y = 0; y < height; y++) {
+            for (int x = 0; x < width; x++) {
+                char ch = grid[y][x];
+                GridPoint point = new GridPoint(x, y);
+                if (ch == '*') {
+                    markers.add(point);
+                }
+                for (Dir dir : actualDirs(grid, x, y)) {
+                    GridPoint next = step(point, dir);
+                    if (next.x < 0 || next.y < 0 || next.x >= width || next.y >= height) {
+                        continue;
+                    }
+                    GridEdge edge = new GridEdge(point, next);
+                    if (boundaryEdges.contains(edge)) {
+                        continue;
+                    }
+                    adjacency.computeIfAbsent(point, unused -> new ArrayList<>()).add(next);
+                    adjacency.computeIfAbsent(next, unused -> new ArrayList<>()).add(point);
+                    boolean dashed = ch == '=' || ch == ':';
+                    char other = grid[next.y][next.x];
+                    dashed = dashed || other == '=' || other == ':';
+                    dashedEdges.put(edge, dashedEdges.getOrDefault(edge, false) || dashed);
+                }
+            }
+        }
+        for (List<GridPoint> neighbors : adjacency.values()) {
+            neighbors.sort(Comparator.comparingInt((GridPoint p) -> p.y).thenComparingInt(p -> p.x));
+            for (int i = neighbors.size() - 1; i > 0; i--) {
+                if (neighbors.get(i).equals(neighbors.get(i - 1))) {
+                    neighbors.remove(i);
+                }
+            }
+        }
+
+        List<StrokePathInfo> paths = tracePaths(grid, adjacency, dashedEdges);
+        List<LooseText> looseTexts = findLooseText(grid, interiorMask);
+        return new Diagram(width, height, shapes, paths, markers, looseTexts, separations);
+    }
