+    private static List<Dir> actualDirs(char[][] grid, int x, int y) {
+        int width = grid.length == 0 ? 0 : grid[0].length;
+        int height = grid.length;
+        if (x < 0 || y < 0 || x >= width || y >= height) {
+            return Collections.emptyList();
+        }
+        char ch = grid[y][x];
+        List<Dir> available = new ArrayList<>();
+        for (Dir dir : Dir.values()) {
+            if (!baseCan(ch, dir)) {
+                continue;
+            }
+            GridPoint next = step(new GridPoint(x, y), dir);
+            if (next.x < 0 || next.y < 0 || next.x >= width || next.y >= height) {
+                continue;
+            }
+            char other = grid[next.y][next.x];
+            if (baseCan(other, opposite(dir))) {
+                available.add(dir);
+            }
+        }
+        if (ch == '/') {
+            if (available.contains(Dir.RIGHT) && available.contains(Dir.DOWN)) {
+                return Arrays.asList(Dir.RIGHT, Dir.DOWN);
+            }
+            if (available.contains(Dir.LEFT) && available.contains(Dir.UP)) {
+                return Arrays.asList(Dir.LEFT, Dir.UP);
+            }
+            if (available.contains(Dir.RIGHT) && available.contains(Dir.UP)) {
+                return Arrays.asList(Dir.RIGHT, Dir.UP);
+            }
+            if (available.contains(Dir.LEFT) && available.contains(Dir.DOWN)) {
+                return Arrays.asList(Dir.LEFT, Dir.DOWN);
+            }
+        }
+        if (ch == '\\') {
+            if (available.contains(Dir.LEFT) && available.contains(Dir.DOWN)) {
+                return Arrays.asList(Dir.LEFT, Dir.DOWN);
+            }
+            if (available.contains(Dir.RIGHT) && available.contains(Dir.UP)) {
+                return Arrays.asList(Dir.RIGHT, Dir.UP);
+            }
+            if (available.contains(Dir.LEFT) && available.contains(Dir.UP)) {
+                return Arrays.asList(Dir.LEFT, Dir.UP);
+            }
+            if (available.contains(Dir.RIGHT) && available.contains(Dir.DOWN)) {
+                return Arrays.asList(Dir.RIGHT, Dir.DOWN);
+            }
+        }
+        return available;
+    }
+
+    private static boolean baseCan(char ch, Dir dir) {
+        switch (ch) {
+            case '-':
+            case '=':
+                return dir == Dir.LEFT || dir == Dir.RIGHT;
+            case '|':
+            case ':':
+                return dir == Dir.UP || dir == Dir.DOWN;
+            case '+':
+            case '*':
+            case '/':
+            case '\\':
+                return true;
+            case '<':
+                return dir == Dir.RIGHT;
+            case '>':
+                return dir == Dir.LEFT;
+            case '^':
+                return dir == Dir.DOWN;
+            case 'v':
+            case 'V':
+                return dir == Dir.UP;
+            default:
+                return false;
+        }
+    }
+
+    private static GridPoint step(GridPoint point, Dir dir) {
+        switch (dir) {
+            case LEFT:
+                return new GridPoint(point.x - 1, point.y);
+            case RIGHT:
+                return new GridPoint(point.x + 1, point.y);
+            case UP:
+                return new GridPoint(point.x, point.y - 1);
+            case DOWN:
+                return new GridPoint(point.x, point.y + 1);
+            default:
+                throw new IllegalStateException();
+        }
+    }
+
+    private static Dir opposite(Dir dir) {
+        switch (dir) {
+            case LEFT:
+                return Dir.RIGHT;
+            case RIGHT:
+                return Dir.LEFT;
+            case UP:
+                return Dir.DOWN;
+            case DOWN:
+                return Dir.UP;
+            default:
+                throw new IllegalStateException();
+        }
+    }
+
+    private static List<StrokePathInfo> tracePaths(
+            char[][] grid,
+            Map<GridPoint, List<GridPoint>> adjacency,
+            Map<GridEdge, Boolean> dashedEdges) {
+        Set<GridEdge> remaining = new HashSet<>(dashedEdges.keySet());
+        List<StrokePathInfo> paths = new ArrayList<>();
+
+        List<GridPoint> startNodes = new ArrayList<>();
+        for (Map.Entry<GridPoint, List<GridPoint>> entry : adjacency.entrySet()) {
+            if (entry.getValue().size() != 2) {
+                startNodes.add(entry.getKey());
+            }
+        }
+        startNodes.sort(Comparator.comparingInt((GridPoint p) -> p.y).thenComparingInt(p -> p.x));
+
+        for (GridPoint start : startNodes) {
+            List<GridPoint> neighbors = adjacency.getOrDefault(start, Collections.emptyList());
+            for (GridPoint next : neighbors) {
+                GridEdge edge = new GridEdge(start, next);
+                if (!remaining.contains(edge)) {
+                    continue;
+                }
+                paths.add(traceOnePath(grid, adjacency, dashedEdges, remaining, start, next));
+            }
+        }
+
+        while (!remaining.isEmpty()) {
+            GridEdge edge = remaining.iterator().next();
+            paths.add(traceOnePath(grid, adjacency, dashedEdges, remaining, edge.a, edge.b));
+        }
+
+        return paths;
+    }
+
+    private static StrokePathInfo traceOnePath(
+            char[][] grid,
+            Map<GridPoint, List<GridPoint>> adjacency,
+            Map<GridEdge, Boolean> dashedEdges,
+            Set<GridEdge> remaining,
+            GridPoint start,
+            GridPoint next) {
+        List<GridPoint> points = new ArrayList<>();
+        points.add(start);
+        boolean dashed = false;
+        GridPoint prev = start;
+        GridPoint curr = next;
+        ArrowDir arrowStart = arrowFor(grid, start, next);
+
+        while (true) {
+            GridEdge edge = new GridEdge(prev, curr);
+            remaining.remove(edge);
+            dashed |= dashedEdges.getOrDefault(edge, false);
+            points.add(curr);
+
+            List<GridPoint> neighbors = adjacency.getOrDefault(curr, Collections.emptyList());
+            List<GridPoint> candidates = new ArrayList<>();
+            for (GridPoint candidate : neighbors) {
+                if (candidate.equals(prev)) {
+                    continue;
+                }
+                if (remaining.contains(new GridEdge(curr, candidate))) {
+                    candidates.add(candidate);
+                }
+            }
+            if (candidates.size() != 1) {
+                break;
+            }
+            prev = curr;
+            curr = candidates.get(0);
+            if (curr.equals(start)) {
+                GridEdge closing = new GridEdge(prev, curr);
+                remaining.remove(closing);
+                dashed |= dashedEdges.getOrDefault(closing, false);
+                points.add(curr);
+                break;
+            }
+        }
+
+        ArrowDir arrowEnd = null;
+        if (points.size() >= 2) {
+            GridPoint last = points.get(points.size() - 1);
+            GridPoint before = points.get(points.size() - 2);
+            arrowEnd = arrowFor(grid, last, before);
+        }
+        return new StrokePathInfo(points, dashed, arrowStart, arrowEnd);
+    }
+
+    private static ArrowDir arrowFor(char[][] grid, GridPoint point, GridPoint other) {
+        if (point.y < 0 || point.y >= grid.length || point.x < 0 || point.x >= grid[point.y].length) {
+            return null;
+        }
+        char ch = grid[point.y][point.x];
+        if (ch == '>' && other.x < point.x) {
+            return ArrowDir.RIGHT;
+        }
+        if (ch == '<' && other.x > point.x) {
+            return ArrowDir.LEFT;
+        }
+        if (ch == '^' && other.y > point.y) {
+            return ArrowDir.UP;
+        }
+        if ((ch == 'v' || ch == 'V') && other.y < point.y) {
+            return ArrowDir.DOWN;
+        }
+        return null;
+    }
+
+    private static List<LooseText> findLooseText(char[][] grid, boolean[][] interiorMask) {
+        List<LooseText> out = new ArrayList<>();
+        for (int y = 0; y < grid.length; y++) {
+            int x = 0;
+            while (x < grid[y].length) {
+                if (interiorMask[y][x] || isLineChar(grid[y][x])) {
+                    x += 1;
+                    continue;
+                }
+                int start = x;
+                StringBuilder raw = new StringBuilder();
+                while (x < grid[y].length && !interiorMask[y][x] && !isLineChar(grid[y][x])) {
+                    raw.append(grid[y][x]);
+                    x += 1;
+                }
+                String rawText = raw.toString();
+                String trimmed = rawText.trim();
+                if (trimmed.isEmpty()) {
+                    continue;
+                }
+                int lead = rawText.indexOf(trimmed);
+                int runStart = start + lead;
+                int runEnd = runStart + trimmed.length();
+                out.add(new LooseText(y, runStart, runEnd, trimmed));
+            }
+        }
+        return out;
+    }
+
+    private static boolean isLineChar(char ch) {
+        return ch == ' ' || ch == '-' || ch == '=' || ch == '|' || ch == ':' || ch == '+' || ch == '/'
+                || ch == '\\' || ch == '<' || ch == '>' || ch == '^' || ch == 'v' || ch == 'V'
+                || ch == '*';
+    }
+
+    private static String renderSvg(Diagram diagram, CliOptions options, boolean forPng) {
+        int width = (int) Math.round((diagram.width + 4.0) * CELL_W * options.scale);
+        int height = (int) Math.round((diagram.height + 4.0) * CELL_H * options.scale);
+        StringBuilder out = new StringBuilder();
+        out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n");
+        out.append("<svg \n");
+        appendf(out, "    xmlns='http://www.w3.org/2000/svg'\n");
+        appendf(out, "    width='%d'\n", width);
+        appendf(out, "    height='%d'\n", height);
+        appendf(out, "    shape-rendering='%s'\n", forPng && options.noAntialias ? "crispEdges" : "geometricPrecision");
+        out.append("    version='1.0'>\n");
+        out.append("  <defs>\n");
+        if (options.svgFontUrl != null) {
+            out.append("    <style type='text/css'>\n");
+            out.append("      @font-face {\n");
+            out.append("        font-family: Custom;\n");
+            out.append("        src: url('").append(escapeAttr(options.svgFontUrl)).append("');\n");
+            out.append("      }\n");
+            out.append("    </style>\n");
+        }
+        out.append("    <filter id='f2' x='0' y='0' width='200%' height='200%'>\n");
+        out.append("      <feOffset result='offOut' in='SourceGraphic' dx='5' dy='5' />\n");
+        out.append("      <feGaussianBlur result='blurOut' in='offOut' stdDeviation='3' />\n");
+        out.append("      <feBlend in='SourceGraphic' in2='blurOut' mode='normal' />\n");
+        out.append("    </filter>\n");
+        out.append("  </defs>\n");
+        out.append("  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round'>\n");
+
+        if (!options.transparent) {
+            if (forPng && options.background.a < 255) {
+                appendf(
+                        out,
+                        "    <rect x='0' y='0' width='%d' height='%d' style='fill: %s; fill-opacity: %.3f'/>\n",
+                        width,
+                        height,
+                        options.background.hexRgb(),
+                        options.background.a / 255.0);
+            } else {
+                appendf(
+                        out,
+                        "    <rect x='0' y='0' width='%d' height='%d' style='fill: %s'/>\n",
+                        width,
+                        height,
+                        options.background.hexRgb());
+            }
+        }
+
+        if (options.debug) {
+            renderSvgDebugGrid(out, width, height, options.scale);
+        }
+
+        for (DiagramShape shape : diagram.shapes) {
+            if (!options.noShadows) {
+                renderSvgShadow(out, shape, options);
+            }
+        }
+        for (Separation separation : diagram.separations) {
+            renderSvgSeparation(out, separation, options);
+        }
+        for (DiagramShape shape : diagram.shapes) {
+            renderSvgShape(out, shape, options);
+        }
+        for (StrokePathInfo path : diagram.paths) {
+            renderSvgPath(out, path, options);
+        }
+        for (GridPoint marker : diagram.markers) {
+            renderSvgMarker(out, marker, options);
+        }
+        for (DiagramShape shape : diagram.shapes) {
+            renderSvgShapeText(out, shape, options);
+        }
+        for (LooseText text : diagram.looseTexts) {
+            renderSvgLooseText(out, text, options);
+        }
