    private static ParseOutcome parseArgs(String[] args) throws CliError {
        if (args.length == 0) {
            return ParseOutcome.usage();
        }
        if (args.length == 1 && ("--help".equals(args[0]) || "-h".equals(args[0]))) {
            return ParseOutcome.weirdJar();
        }
        for (String arg : args) {
            if ("--help".equals(arg)) {
                return ParseOutcome.usage();
            }
        }

        CliOptions options = new CliOptions();
        for (int i = 0; i < args.length; i++) {
            String arg = args[i];
            switch (arg) {
                case "-A":
                case "--no-antialias":
                    options.noAntialias = true;
                    options.reportedOptions.add("no-antialias");
                    break;
                case "-b":
                case "--background":
                    String background = requireValue(args, ++i, "-b");
                    options.background = parseBackground(background);
                    options.backgroundRaw = background;
                    options.reportedOptions.add("background = " + background);
                    break;
                case "-d":
                case "--debug":
                    options.debug = true;
                    options.reportedOptions.add("debug");
                    break;
                case "-E":
                case "--no-separation":
                    options.noSeparation = true;
                    options.reportedOptions.add("no-separation");
                    break;
                case "-e":
                case "--encoding":
                    String encoding = requireValue(args, ++i, "-e");
                    options.encoding = encoding;
                    options.reportedOptions.add("encoding = " + encoding);
                    break;
                case "-h":
                case "--html":
                    options.html = true;
                    options.reportedOptions.add("html");
                    break;
                case "-o":
                case "--overwrite":
                    options.overwrite = true;
                    options.reportedOptions.add("overwrite");
                    break;
                case "-r":
                case "--round-corners":
                    options.roundCorners = true;
                    options.reportedOptions.add("round-corners");
                    break;
                case "-S":
                case "--no-shadows":
                    options.noShadows = true;
                    options.reportedOptions.add("no-shadows");
                    break;
                case "-s":
                case "--scale":
                    String scaleValue = requireValue(args, ++i, "-s");
                    try {
                        options.scale = Double.parseDouble(scaleValue);
                    } catch (NumberFormatException e) {
                        throw new CliError("Error: For input string: \"" + scaleValue + "\"", 2, true);
                    }
                    options.reportedOptions.add("scale = " + scaleValue);
                    break;
                case "--svg":
                    options.svg = true;
                    options.reportedOptions.add("svg");
                    break;
                case "--svg-font-url":
                    String fontUrl = requireValue(args, ++i, "--svg-font-url");
                    options.svgFontUrl = fontUrl;
                    options.reportedOptions.add("svg-font-url = " + fontUrl);
                    break;
                case "-T":
                case "--transparent":
                    options.transparent = true;
                    options.reportedOptions.add("transparent");
                    break;
                case "-t":
                case "--tabs":
                    String tabsValue = requireValue(args, ++i, "-t");
                    try {
                        options.tabs = Integer.parseInt(tabsValue);
                    } catch (NumberFormatException e) {
                        throw new CliError("Error: For input string: \"" + tabsValue + "\"", 2, true);
                    }
                    options.reportedOptions.add("tabs = " + tabsValue);
                    break;
                case "-v":
                case "--verbose":
                    options.verbose = true;
                    options.reportedOptions.add("verbose");
                    break;
                case "-W":
                case "--fixed-slope":
                    options.fixedSlope = true;
                    options.reportedOptions.add("fixed-slope");
                    break;
                default:
                    if (arg.startsWith("-")) {
                        throw new CliError("Unrecognized option: " + arg, 2, true);
                    }
                    if (options.positionals.size() < 2) {
                        options.positionals.add(arg);
                    }
                    break;
            }
        }

        if (options.positionals.isEmpty()) {
            return ParseOutcome.usage();
        }
        return ParseOutcome.run(options);
