    private static RgbaColor parseBackground(String value) throws CliError {
        if (!(value.length() == 6 || value.length() == 8) || !value.matches("[0-9a-fA-F]+")) {
            throw new CliError(
                    "Error: Cannot interpret \"" + value
                            + "\" as background colour. It needs to be a 6- or 8-digit hex number, depending on whether you have transparency or not (same as HTML).",
                    2,
                    true);
        }
        long parsed = Long.parseLong(value, 16);
        if (value.length() == 6) {
            return new RgbaColor(
                    (int) ((parsed >> 16) & 0xff),
                    (int) ((parsed >> 8) & 0xff),
                    (int) (parsed & 0xff),
                    255);
        }
        return new RgbaColor(
                (int) ((parsed >> 24) & 0xff),
                (int) ((parsed >> 16) & 0xff),
                (int) ((parsed >> 8) & 0xff),
                (int) (parsed & 0xff));
    }

