    private static int runDiagram(CliOptions options) throws Exception {
        Path input = Paths.get(options.positionals.get(0));
        System.out.println("Reading file: " + input);
        if (!Files.exists(input)) {
            System.out.println("Error: File " + input + " does not exist");
            return 1;
        }
        List<String> lines = readLines(input, options);
        if (options.verbose) {
            printVerboseGrid(lines);
        }
        Path output;
        if (options.positionals.size() > 1) {
            output = Paths.get(options.positionals.get(1));
        } else {
            output = deriveDiagramOutput(input, options.svg, options.overwrite);
        }
        System.out.println("Rendering to file: " + output);
        Diagram diagram = buildDiagram(lines, options);
        if (options.svg) {
            Files.write(output, renderSvg(diagram, options, false).getBytes(StandardCharsets.UTF_8));
        } else {
            renderPng(diagram, options, output);
        }
        System.out.println("Done in 0sec");
        return 0;
    }

    private static int runHtml(CliOptions options) throws Exception {
        Path input = Paths.get(options.positionals.get(0));
        if (!Files.exists(input)) {
            System.out.println("Error: File " + input + " does not exist");
            return 1;
        }

        Path output = options.positionals.size() > 1
                ? Paths.get(options.positionals.get(1))
                : deriveHtmlOutput(input);
        if (Files.exists(output) && !options.overwrite) {
            System.out.println(
                    "Error: File " + output
                            + " exists. If you would like to overwrite it, please use the --overwrite option.");
            return 0;
        }

        String html = readText(input, options);
        Matcher matcher = PRE_PATTERN.matcher(html);
        StringBuilder processed = new StringBuilder();
        List<HtmlDiagram> diagrams = new ArrayList<>();
        int last = 0;
        int nextIndex = 1;
        while (matcher.find()) {
            processed.append(html, last, matcher.start());
            String attrs = matcher.group(1) == null ? "" : matcher.group(1);
            String classValue = "";
            Matcher classMatcher = CLASS_PATTERN.matcher(attrs);
            if (classMatcher.find()) {
                classValue = classMatcher.group(1);
            }
            boolean isTextDiagram = false;
            for (String item : classValue.split("\\s+")) {
                if ("textdiagram".equalsIgnoreCase(item)) {
                    isTextDiagram = true;
                    break;
                }
            }
            if (!isTextDiagram) {
                processed.append(matcher.group());
                last = matcher.end();
                continue;
            }
            String name = null;
            Matcher idMatcher = ID_PATTERN.matcher(attrs);
            if (idMatcher.find()) {
                name = idMatcher.group(1);
            }
            if (name == null || name.isEmpty()) {
                name = "ditaa_diagram_" + nextIndex;
                nextIndex += 1;
            }
            diagrams.add(new HtmlDiagram(name, matcher.group(2)));
            processed.append("<img src=\"images/").append(name).append(".png\" />");
            last = matcher.end();
        }
        processed.append(html.substring(last));

        Files.write(output, processed.toString().getBytes(StandardCharsets.UTF_8));
        System.out.println("Converting HTML file (" + input + " -> " + output + ")... done");
        System.out.println("Generating diagrams... ");

        Path imagesDir = output.getParent() == null ? Paths.get("images") : output.getParent().resolve("images");
        Files.createDirectories(imagesDir);
        for (HtmlDiagram diagram : diagrams) {
            Path image = imagesDir.resolve(diagram.name + ".png");
            if (Files.exists(image) && !options.overwrite) {
                System.out.println(
                        "Error: Cannot overwrite file images/" + diagram.name
                                + ".png, file already exists. Use the --overwrite option if you would like to allow file overwrite.");
                continue;
            }
            List<String> lines = normalizeLines(diagram.text, options.tabs);
            renderPng(buildDiagram(lines, options), options, image);
            System.out.println("\t" + image);
        }
        System.out.println();
        System.out.println("...done");
        return 0;
    }

    private static List<String> readLines(Path path, CliOptions options) throws IOException {
        return normalizeLines(readText(path, options), options.tabs);
    }

    private static String readText(Path path, CliOptions options) throws IOException {
        byte[] data = Files.readAllBytes(path);
        Charset charset;
        if (options.encoding != null) {
            charset = Charset.forName(options.encoding);
        } else {
            charset = StandardCharsets.UTF_8;
        }
        return new String(data, charset);
    }

    private static List<String> normalizeLines(String text, int tabs) {
        String normalized = text.replace("\r", "");
        String[] raw = normalized.split("\n", -1);
        List<String> lines = new ArrayList<>();
        for (String line : raw) {
            lines.add(expandTabs(line, tabs));
        }
        if (!lines.isEmpty() && lines.get(lines.size() - 1).isEmpty()) {
            lines.remove(lines.size() - 1);
        }
        if (lines.isEmpty()) {
            lines.add("");
        }
        return lines;
    }

    private static String expandTabs(String line, int tabs) {
        StringBuilder out = new StringBuilder();
        int tabstop = Math.max(1, tabs);
        for (int i = 0; i < line.length(); i++) {
            char ch = line.charAt(i);
            if (ch == '\t') {
                int spaces = tabstop - (out.length() % tabstop);
                for (int j = 0; j < spaces; j++) {
                    out.append(' ');
                }
            } else {
                out.append(ch);
            }
        }
        return out.toString();
    }

    private static Path deriveDiagramOutput(Path input, boolean svg, boolean overwrite) {
        String ext = svg ? "svg" : "png";
        Path base = replaceExtension(input, ext);
        if (overwrite || !Files.exists(base)) {
            return base;
        }
        Path parent = input.getParent() == null ? Paths.get("") : input.getParent();
        String stem = fileStem(input);
        int index = 2;
        while (true) {
            Path candidate = parent.resolve(stem + "_" + index + "." + ext);
            if (!Files.exists(candidate)) {
                return candidate;
            }
            index += 1;
        }
    }

    private static Path replaceExtension(Path input, String ext) {
        Path parent = input.getParent() == null ? Paths.get("") : input.getParent();
        return parent.resolve(fileStem(input) + "." + ext);
    }

    private static Path deriveHtmlOutput(Path input) {
        Path parent = input.getParent() == null ? Paths.get("") : input.getParent();
        return parent.resolve(fileStem(input) + "_processed.html");
    }

    private static String fileStem(Path path) {
        String name = path.getFileName() == null ? path.toString() : path.getFileName().toString();
        int dot = name.lastIndexOf('.');
        return dot == -1 ? name : name.substring(0, dot);
    }

    private static void printVerboseGrid(List<String> lines) {
        int contentWidth = 0;
        for (String line : lines) {
            contentWidth = Math.max(contentWidth, line.length());
        }
        int width = contentWidth + 4;
        List<String> rows = new ArrayList<>();
        rows.add(repeat(' ', width));
        rows.add(repeat(' ', width));
        for (String line : lines) {
            String row = "  " + line;
            if (row.length() < width) {
                row = row + repeat(' ', width - row.length());
            }
            rows.add(row);
        }
        rows.add(repeat(' ', width));
        rows.add(repeat(' ', width));

        System.out.println("Using grid:");
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < width; i++) {
            digits.append((char) ('0' + (i % 10)));
        }
        System.out.println("    " + digits);
        for (int i = 0; i < rows.size(); i++) {
            System.out.printf(Locale.US, "%2d (%s)%n", i, rows.get(i));
        }
    }

    private static String repeat(char ch, int count) {
        char[] chars = new char[count];
        Arrays.fill(chars, ch);
        return new String(chars);
    }

    private static Diagram buildDiagram(List<String> lines, CliOptions options) {
        int width = 0;
        for (String line : lines) {
            width = Math.max(width, line.length());
        }
        int height = lines.size();
        char[][] grid = new char[height][width];
        for (int y = 0; y < height; y++) {
            String line = lines.get(y);
