                        }
                        for (int x = x0; x < x1; x++) {
                            boundaryEdges.add(new GridEdge(new GridPoint(x, y0), new GridPoint(x + 1, y0)));
                            boundaryEdges.add(new GridEdge(new GridPoint(x, y1), new GridPoint(x + 1, y1)));
                        }
                        for (int y = y0; y < y1; y++) {
                            boundaryEdges.add(new GridEdge(new GridPoint(x0, y), new GridPoint(x0, y + 1)));
                            boundaryEdges.add(new GridEdge(new GridPoint(x1, y), new GridPoint(x1, y + 1)));
                        }

                        shapes.add(new DiagramShape(x0, y0, x1, y1, kind, rounded, fill, textColor, textLines));
                    }
                }
            }
        }

        shapes.sort((a, b) -> Integer.compare((b.x1 - b.x0) * (b.y1 - b.y0), (a.x1 - a.x0) * (a.y1 - a.y0)));

        List<Separation> separations = options.noSeparation ? new ArrayList<>() : computeSeparations(shapes);
        Map<GridPoint, List<GridPoint>> adjacency = new HashMap<>();
        Map<GridEdge, Boolean> dashedEdges = new HashMap<>();
        List<GridPoint> markers = new ArrayList<>();

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                char ch = grid[y][x];
                GridPoint point = new GridPoint(x, y);
                if (ch == '*') {
                    markers.add(point);
                }
                for (Dir dir : actualDirs(grid, x, y)) {
                    GridPoint next = step(point, dir);
                    if (next.x < 0 || next.y < 0 || next.x >= width || next.y >= height) {
                        continue;
                    }
                    GridEdge edge = new GridEdge(point, next);
                    if (boundaryEdges.contains(edge)) {
                        continue;
                    }
                    adjacency.computeIfAbsent(point, unused -> new ArrayList<>()).add(next);
                    adjacency.computeIfAbsent(next, unused -> new ArrayList<>()).add(point);
                    boolean dashed = ch == '=' || ch == ':';
                    char other = grid[next.y][next.x];
                    dashed = dashed || other == '=' || other == ':';
                    dashedEdges.put(edge, dashedEdges.getOrDefault(edge, false) || dashed);
                }
            }
        }
        for (List<GridPoint> neighbors : adjacency.values()) {
            neighbors.sort(Comparator.comparingInt((GridPoint p) -> p.y).thenComparingInt(p -> p.x));
            for (int i = neighbors.size() - 1; i > 0; i--) {
                if (neighbors.get(i).equals(neighbors.get(i - 1))) {
                    neighbors.remove(i);
                }
            }
        }

        List<StrokePathInfo> paths = tracePaths(grid, adjacency, dashedEdges);
        List<LooseText> looseTexts = findLooseText(grid, interiorMask);
        return new Diagram(width, height, shapes, paths, markers, looseTexts, separations);
    }

    private static ShapeKind detectShapeKind(String inside) {
        Matcher matcher = MARKER_PATTERN.matcher(inside);
        if (!matcher.find()) {
            return ShapeKind.RECT;
        }
        switch (matcher.group(1)) {
            case "d":
                return ShapeKind.DOCUMENT;
            case "s":
                return ShapeKind.STORAGE;
            case "o":
                return ShapeKind.ELLIPSE;
            case "mo":
                return ShapeKind.MANUAL_OPERATION;
            case "c":
                return ShapeKind.DECISION;
            case "tr":
                return ShapeKind.TRAPEZOID;
            case "io":
                return ShapeKind.IO;
            default:
                return ShapeKind.RECT;
        }
    }

    private static RgbaColor detectFillColor(String inside) {
        Matcher matcher = COLOR_PATTERN.matcher(inside);
        if (!matcher.find()) {
            return new RgbaColor(255, 255, 255, 255);
        }
        return namedColor(matcher.group(1));
    }

    private static boolean isHorizontalEdge(char ch) {
        return ch == '-' || ch == '=' || ch == '+';
    }

    private static boolean isVerticalEdge(char ch) {
        return ch == '|' || ch == ':' || ch == '+';
    }

    private static RgbaColor namedColor(String name) {
        switch (name) {
            case "RED":
                return new RgbaColor(224, 48, 32, 255);
            case "GRE":
                return new RgbaColor(144, 208, 144, 255);
            case "BLU":
                return new RgbaColor(80, 80, 176, 255);
            case "PNK":
                return new RgbaColor(240, 160, 160, 255);
            case "YEL":
                return new RgbaColor(240, 240, 48, 255);
            case "BLK":
                return new RgbaColor(0, 0, 0, 255);
            default:
                return new RgbaColor(255, 255, 255, 255);
        }
    }

    private static List<Separation> computeSeparations(List<DiagramShape> shapes) {
        List<Separation> out = new ArrayList<>();
        for (int i = 0; i < shapes.size(); i++) {
            for (int j = i + 1; j < shapes.size(); j++) {
                DiagramShape a = shapes.get(i);
                DiagramShape b = shapes.get(j);
                if (a.x1 == b.x0 || b.x1 == a.x0) {
                    int coord = a.x1 == b.x0 ? a.x1 : b.x1;
                    int start = Math.max(a.y0, b.y0);
                    int end = Math.min(a.y1, b.y1);
                    if (end - start >= 1) {
                        out.add(new Separation(true, coord, start, end));
                    }
                }
                if (a.y1 == b.y0 || b.y1 == a.y0) {
                    int coord = a.y1 == b.y0 ? a.y1 : b.y1;
                    int start = Math.max(a.x0, b.x0);
                    int end = Math.min(a.x1, b.x1);
                    if (end - start >= 1) {
                        out.add(new Separation(false, coord, start, end));
                    }
                }
            }
        }
        return out;
    }

    private static List<Dir> actualDirs(char[][] grid, int x, int y) {
        int width = grid.length == 0 ? 0 : grid[0].length;
        int height = grid.length;
        if (x < 0 || y < 0 || x >= width || y >= height) {
            return Collections.emptyList();
        }
        char ch = grid[y][x];
        List<Dir> available = new ArrayList<>();
        for (Dir dir : Dir.values()) {
            if (!baseCan(ch, dir)) {
                continue;
            }
            GridPoint next = step(new GridPoint(x, y), dir);
            if (next.x < 0 || next.y < 0 || next.x >= width || next.y >= height) {
                continue;
            }
            char other = grid[next.y][next.x];
            if (baseCan(other, opposite(dir))) {
                available.add(dir);
            }
        }
        if (ch == '/') {
            if (available.contains(Dir.RIGHT) && available.contains(Dir.DOWN)) {
                return Arrays.asList(Dir.RIGHT, Dir.DOWN);
            }
            if (available.contains(Dir.LEFT) && available.contains(Dir.UP)) {
                return Arrays.asList(Dir.LEFT, Dir.UP);
            }
            if (available.contains(Dir.RIGHT) && available.contains(Dir.UP)) {
                return Arrays.asList(Dir.RIGHT, Dir.UP);
            }
            if (available.contains(Dir.LEFT) && available.contains(Dir.DOWN)) {
                return Arrays.asList(Dir.LEFT, Dir.DOWN);
            }
        }
        if (ch == '\\') {
            if (available.contains(Dir.LEFT) && available.contains(Dir.DOWN)) {
                return Arrays.asList(Dir.LEFT, Dir.DOWN);
            }
            if (available.contains(Dir.RIGHT) && available.contains(Dir.UP)) {
                return Arrays.asList(Dir.RIGHT, Dir.UP);
            }
            if (available.contains(Dir.LEFT) && available.contains(Dir.UP)) {
                return Arrays.asList(Dir.LEFT, Dir.UP);
            }
            if (available.contains(Dir.RIGHT) && available.contains(Dir.DOWN)) {
                return Arrays.asList(Dir.RIGHT, Dir.DOWN);
            }
        }
        return available;
    }

    private static boolean baseCan(char ch, Dir dir) {
        switch (ch) {
            case '-':
            case '=':
                return dir == Dir.LEFT || dir == Dir.RIGHT;
            case '|':
            case ':':
                return dir == Dir.UP || dir == Dir.DOWN;
            case '+':
            case '*':
            case '/':
            case '\\':
                return true;
            case '<':
                return dir == Dir.RIGHT;
            case '>':
                return dir == Dir.LEFT;
            case '^':
                return dir == Dir.DOWN;
            case 'v':
            case 'V':
                return dir == Dir.UP;
            default:
                return false;
        }
    }

    private static GridPoint step(GridPoint point, Dir dir) {
        switch (dir) {
            case LEFT:
                return new GridPoint(point.x - 1, point.y);
            case RIGHT:
                return new GridPoint(point.x + 1, point.y);
            case UP:
                return new GridPoint(point.x, point.y - 1);
            case DOWN:
                return new GridPoint(point.x, point.y + 1);
            default:
                throw new IllegalStateException();
        }
    }

    private static Dir opposite(Dir dir) {
        switch (dir) {
            case LEFT:
                return Dir.RIGHT;
            case RIGHT:
                return Dir.LEFT;
            case UP:
                return Dir.DOWN;
            case DOWN:
                return Dir.UP;
            default:
                throw new IllegalStateException();
        }
    }

    private static List<StrokePathInfo> tracePaths(
            char[][] grid,
            Map<GridPoint, List<GridPoint>> adjacency,
            Map<GridEdge, Boolean> dashedEdges) {
        Set<GridEdge> remaining = new HashSet<>(dashedEdges.keySet());
        List<StrokePathInfo> paths = new ArrayList<>();

        List<GridPoint> startNodes = new ArrayList<>();
        for (Map.Entry<GridPoint, List<GridPoint>> entry : adjacency.entrySet()) {
            if (entry.getValue().size() != 2) {
                startNodes.add(entry.getKey());
            }
        }
        startNodes.sort(Comparator.comparingInt((GridPoint p) -> p.y).thenComparingInt(p -> p.x));

        for (GridPoint start : startNodes) {
            List<GridPoint> neighbors = adjacency.getOrDefault(start, Collections.emptyList());
            for (GridPoint next : neighbors) {
                GridEdge edge = new GridEdge(start, next);
                if (!remaining.contains(edge)) {
                    continue;
                }
                paths.add(traceOnePath(grid, adjacency, dashedEdges, remaining, start, next));
            }
        }

        while (!remaining.isEmpty()) {
            GridEdge edge = remaining.iterator().next();
            paths.add(traceOnePath(grid, adjacency, dashedEdges, remaining, edge.a, edge.b));
        }

        return paths;
    }

    private static StrokePathInfo traceOnePath(
            char[][] grid,
            Map<GridPoint, List<GridPoint>> adjacency,
            Map<GridEdge, Boolean> dashedEdges,
            Set<GridEdge> remaining,
            GridPoint start,
            GridPoint next) {
        List<GridPoint> points = new ArrayList<>();
        points.add(start);
        boolean dashed = false;
        GridPoint prev = start;
        GridPoint curr = next;
        ArrowDir arrowStart = arrowFor(grid, start, next);

        while (true) {
            GridEdge edge = new GridEdge(prev, curr);
            remaining.remove(edge);
            dashed |= dashedEdges.getOrDefault(edge, false);
            points.add(curr);

            List<GridPoint> neighbors = adjacency.getOrDefault(curr, Collections.emptyList());
            List<GridPoint> candidates = new ArrayList<>();
            for (GridPoint candidate : neighbors) {
                if (candidate.equals(prev)) {
                    continue;
                }
                if (remaining.contains(new GridEdge(curr, candidate))) {
                    candidates.add(candidate);
                }
            }
            if (candidates.size() != 1) {
                break;
            }
            prev = curr;
            curr = candidates.get(0);
            if (curr.equals(start)) {
                GridEdge closing = new GridEdge(prev, curr);
                remaining.remove(closing);
                dashed |= dashedEdges.getOrDefault(closing, false);
                points.add(curr);
                break;
            }
        }

        ArrowDir arrowEnd = null;
        if (points.size() >= 2) {
            GridPoint last = points.get(points.size() - 1);
            GridPoint before = points.get(points.size() - 2);
            arrowEnd = arrowFor(grid, last, before);
        }
        return new StrokePathInfo(points, dashed, arrowStart, arrowEnd);
    }

    private static ArrowDir arrowFor(char[][] grid, GridPoint point, GridPoint other) {
        if (point.y < 0 || point.y >= grid.length || point.x < 0 || point.x >= grid[point.y].length) {
            return null;
        }
        char ch = grid[point.y][point.x];
        if (ch == '>' && other.x < point.x) {
            return ArrowDir.RIGHT;
        }
        if (ch == '<' && other.x > point.x) {
            return ArrowDir.LEFT;
        }
        if (ch == '^' && other.y > point.y) {
            return ArrowDir.UP;
        }
        if ((ch == 'v' || ch == 'V') && other.y < point.y) {
            return ArrowDir.DOWN;
        }
        return null;
    }

    private static List<LooseText> findLooseText(char[][] grid, boolean[][] interiorMask) {
        List<LooseText> out = new ArrayList<>();
        for (int y = 0; y < grid.length; y++) {
            int x = 0;
            while (x < grid[y].length) {
                if (interiorMask[y][x] || isLineChar(grid[y][x])) {
                    x += 1;
                    continue;
                }
                int start = x;
                StringBuilder raw = new StringBuilder();
                while (x < grid[y].length && !interiorMask[y][x] && !isLineChar(grid[y][x])) {
                    raw.append(grid[y][x]);
                    x += 1;
                }
                String rawText = raw.toString();
                String trimmed = rawText.trim();
                if (trimmed.isEmpty()) {
                    continue;
                }
                int lead = rawText.indexOf(trimmed);
                int runStart = start + lead;
                int runEnd = runStart + trimmed.length();
                out.add(new LooseText(y, runStart, runEnd, trimmed));
            }
        }
        return out;
    }

    private static boolean isLineChar(char ch) {
        return ch == ' ' || ch == '-' || ch == '=' || ch == '|' || ch == ':' || ch == '+' || ch == '/'
                || ch == '\\' || ch == '<' || ch == '>' || ch == '^' || ch == 'v' || ch == 'V'
                || ch == '*';
    }

    private static String renderSvg(Diagram diagram, CliOptions options, boolean forPng) {
        int width = (int) Math.round((diagram.width + 4.0) * CELL_W * options.scale);
        int height = (int) Math.round((diagram.height + 4.0) * CELL_H * options.scale);
        StringBuilder out = new StringBuilder();
        out.append("<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n");
        out.append("<svg \n");
        appendf(out, "    xmlns='http://www.w3.org/2000/svg'\n");
        appendf(out, "    width='%d'\n", width);
        appendf(out, "    height='%d'\n", height);
        appendf(out, "    shape-rendering='%s'\n", forPng && options.noAntialias ? "crispEdges" : "geometricPrecision");
        out.append("    version='1.0'>\n");
        out.append("  <defs>\n");
        if (options.svgFontUrl != null) {
            out.append("    <style type='text/css'>\n");
            out.append("      @font-face {\n");
            out.append("        font-family: Custom;\n");
            out.append("        src: url('").append(escapeAttr(options.svgFontUrl)).append("');\n");
            out.append("      }\n");
            out.append("    </style>\n");
        }
        out.append("    <filter id='f2' x='0' y='0' width='200%' height='200%'>\n");
        out.append("      <feOffset result='offOut' in='SourceGraphic' dx='5' dy='5' />\n");
        out.append("      <feGaussianBlur result='blurOut' in='offOut' stdDeviation='3' />\n");
        out.append("      <feBlend in='SourceGraphic' in2='blurOut' mode='normal' />\n");
        out.append("    </filter>\n");
        out.append("  </defs>\n");
        out.append("  <g stroke-width='1' stroke-linecap='square' stroke-linejoin='round'>\n");

        if (!options.transparent) {
            if (forPng && options.background.a < 255) {
                appendf(
                        out,
                        "    <rect x='0' y='0' width='%d' height='%d' style='fill: %s; fill-opacity: %.3f'/>\n",
                        width,
                        height,
                        options.background.hexRgb(),
                        options.background.a / 255.0);
            } else {
                appendf(
                        out,
                        "    <rect x='0' y='0' width='%d' height='%d' style='fill: %s'/>\n",
                        width,
                        height,
                        options.background.hexRgb());
            }
        }

        if (options.debug) {
            renderSvgDebugGrid(out, width, height, options.scale);
        }

        for (DiagramShape shape : diagram.shapes) {
            if (!options.noShadows) {
                renderSvgShadow(out, shape, options);
            }
        }
        for (Separation separation : diagram.separations) {
            renderSvgSeparation(out, separation, options);
        }
        for (DiagramShape shape : diagram.shapes) {
            renderSvgShape(out, shape, options);
        }
        for (StrokePathInfo path : diagram.paths) {
            renderSvgPath(out, path, options);
        }
        for (GridPoint marker : diagram.markers) {
            renderSvgMarker(out, marker, options);
        }
        for (DiagramShape shape : diagram.shapes) {
            renderSvgShapeText(out, shape, options);
        }
        for (LooseText text : diagram.looseTexts) {
            renderSvgLooseText(out, text, options);
        }

        out.append("  </g>\n");
        out.append("</svg>\n");
        return out.toString();
    }

    private static void renderSvgDebugGrid(StringBuilder out, int width, int height, double scale) {
        double stepX = CELL_W * scale;
        double stepY = CELL_H * scale;
        for (double x = 0; x <= width; x += stepX) {
            appendf(
                    out,
                    "    <path stroke='#666666' stroke-width='0.5' fill='none' d='M%.1f 0 L%.1f %d' />\n",
                    x,
                    x,
                    height);
        }
        for (double y = 0; y <= height; y += stepY) {
            appendf(
                    out,
                    "    <path stroke='#666666' stroke-width='0.5' fill='none' d='M0 %.1f L%d %.1f' />\n",
                    y,
                    width,
                    y);
        }
    }

    private static void renderSvgShadow(StringBuilder out, DiagramShape shape, CliOptions options) {
        ShapeGeometry geometry = buildGeometry(shape, options.scale, options.fixedSlope);
        appendf(
                out,
                "    <path stroke='gray' fill='gray' filter='url(#f2)' d='%s' />\n",
                geometry.svgPath);
    }

    private static void renderSvgSeparation(StringBuilder out, Separation separation, CliOptions options) {
        if (separation.vertical) {
            double x = pxX(separation.coord, options.scale);
            double y0 = pxY(separation.start, options.scale);
            double y1 = pxY(separation.end, options.scale);
            appendf(
                    out,
                    "    <path stroke='#ffffff' stroke-width='%.1f' stroke-linecap='square' fill='none' d='M%.1f %.1f L%.1f %.1f' />\n",
                    3.0 * options.scale,
                    x,
                    y0,
                    x,
                    y1);
        } else {
            double y = pxY(separation.coord, options.scale);
            double x0 = pxX(separation.start, options.scale);
            double x1 = pxX(separation.end, options.scale);
            appendf(
                    out,
                    "    <path stroke='#ffffff' stroke-width='%.1f' stroke-linecap='square' fill='none' d='M%.1f %.1f L%.1f %.1f' />\n",
                    3.0 * options.scale,
                    x0,
                    y,
                    x1,
                    y);
        }
    }

    private static void renderSvgShape(StringBuilder out, DiagramShape shape, CliOptions options) {
        ShapeGeometry geometry = buildGeometry(shape, options.scale, options.fixedSlope);
        if (shape.kind == ShapeKind.STORAGE) {
            appendf(
                    out,
                    "    <path stroke='white' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='%s' d='%s' />\n",
                    shape.fill.hexRgb(),
                    geometry.svgPath);
            appendf(
                    out,
                    "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='none' d='%s' />\n",
                    geometry.svgPath);
        } else {
            appendf(
                    out,
                    "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='%s' d='%s' />\n",
                    shape.fill.hexRgb(),
                    geometry.svgPath);
        }
    }

    private static void renderSvgPath(StringBuilder out, StrokePathInfo path, CliOptions options) {
        if (path.points.size() < 2) {
            return;
        }
        StringBuilder d = new StringBuilder();
        for (int i = 0; i < path.points.size(); i++) {
            GridPoint point = path.points.get(i);
            double x = pxX(point.x, options.scale);
            double y = pxY(point.y, options.scale);
            if (i == 0) {
                appendf(d, "M%.1f %.1f ", x, y);
            } else {
                appendf(d, "L%.1f %.1f ", x, y);
            }
        }
        if (path.dashed) {
            appendf(
                    out,
                    "    <path stroke='#000000' stroke-width='1.0' stroke-dasharray='5.0,5.0' stroke-miterlimit='0' stroke-linecap='butt' stroke-linejoin='round' fill='none' d='%s' />\n",
                    d);
        } else {
            appendf(
                    out,
                    "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='none' d='%s' />\n",
                    d);
        }
        if (path.arrowStart != null) {
            renderSvgArrow(out, path.points.get(0), path.arrowStart, options.scale);
        }
        if (path.arrowEnd != null) {
            renderSvgArrow(out, path.points.get(path.points.size() - 1), path.arrowEnd, options.scale);
        }
    }

    private static void renderSvgArrow(StringBuilder out, GridPoint point, ArrowDir dir, double scale) {
        double x = pxX(point.x, scale);
        double y = pxY(point.y, scale);
        double[] coords = arrowCoords(x, y, dir, scale);
        appendf(
                out,
                "    <path stroke='none' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='#000000' d='M%.1f %.1f L%.1f %.1f L%.1f %.1f z' />\n",
                coords[0],
                coords[1],
                coords[2],
                coords[3],
                coords[4],
                coords[5]);
    }

    private static void renderSvgMarker(StringBuilder out, GridPoint point, CliOptions options) {
        double x = pxX(point.x, options.scale);
        double y = pxY(point.y, options.scale);
        double r = 4.0 * options.scale;
        appendf(
                out,
                "    <path stroke='#000000' stroke-width='1.0' stroke-linecap='round' stroke-linejoin='round' fill='white' d='%s' />\n",
                circlePath(x, y, r));
    }

    private static void renderSvgShapeText(StringBuilder out, DiagramShape shape, CliOptions options) {
        for (TextLayout layout : layoutShapeText(shape, options.scale, options.svgFontUrl != null ? "Custom" : "Courier")) {
            if (layout.bullet) {
                appendf(
                        out,
                        "    <path stroke='none' fill='%s' d='%s' />\n",
                        shape.textColor.hexRgb(),
                        circlePath(layout.bulletX, layout.baseline - layout.bulletRadius, layout.bulletRadius));
                appendf(
                        out,
                        "    <text x='%.1f' y='%.1f' font-family='%s' font-size='%d' stroke='none' fill='%s'>%s</text>\n",
                        layout.x,
                        layout.baseline,
                        layout.fontFamily,
                        layout.fontSize,
                        shape.textColor.hexRgb(),
                        cdata(layout.text));
            } else {
                appendf(
                        out,
                        "    <text x='%.1f' y='%.1f' font-family='%s' font-size='%d' stroke='none' fill='%s'>%s</text>\n",
                        layout.x,
                        layout.baseline,
                        layout.fontFamily,
                        layout.fontSize,
                        shape.textColor.hexRgb(),
                        cdata(layout.text));
            }
        }
    }

    private static void renderSvgLooseText(StringBuilder out, LooseText text, CliOptions options) {
        String family = options.svgFontUrl != null ? "Custom" : "Courier";
        TextMetrics metrics = measureAndFit(text.text, (pxX(text.end, options.scale) - pxX(text.start, options.scale)),
                family, BASE_FONT_SIZE);
        double centerX = (pxX(text.start, options.scale) + pxX(text.end, options.scale)) / 2.0;
        double baseline = pxY(text.row, options.scale) + metrics.baselineOffset();
        double x = centerX - metrics.width / 2.0;
        appendf(
                out,
                "    <text x='%.1f' y='%.1f' font-family='%s' font-size='%d' stroke='none' fill='#000000'>%s</text>\n",
                x,
                baseline,
                family,
                metrics.fontSize,
                cdata(text.text));
    }

    private static List<TextLayout> layoutShapeText(DiagramShape shape, double scale, String family) {
        List<TextLayout> layouts = new ArrayList<>();
        if (shape.textLines.isEmpty()) {
            return layouts;
        }
        double left = pxX(shape.x0, scale);
        double right = pxX(shape.x1, scale);
        double top = pxY(shape.y0, scale);
        double bottom = pxY(shape.y1, scale);
        double centerX = (left + right) / 2.0;
        double centerY = (top + bottom) / 2.0;
        double textWidth = Math.max(16.0 * scale, right - left - 16.0 * scale);
        double gap = CELL_H * scale;
        double firstCenter = centerY - ((shape.textLines.size() - 1) * gap) / 2.0;

        for (int i = 0; i < shape.textLines.size(); i++) {
            TextEntry line = shape.textLines.get(i);
            TextMetrics metrics = measureAndFit(line.text, textWidth, family, BASE_FONT_SIZE);
            double baseline = firstCenter + i * gap + metrics.baselineOffset();
            if (line.bullet) {
                double bulletX = left + 18.0 * scale;
                double textX = left + 28.0 * scale;
                layouts.add(new TextLayout(line.text, true, metrics.fontSize, family, textX, baseline,
                        bulletX, 3.0 * scale));
            } else {
                double x = centerX - metrics.width / 2.0;
                layouts.add(new TextLayout(line.text, false, metrics.fontSize, family, x, baseline, 0, 0));
            }
        }
        return layouts;
    }

    private static TextMetrics measureAndFit(String text, double maxWidth, String family, int baseSize) {
        int size = baseSize;
        FontMetrics metrics = fontMetrics(family, size);
        while (size > 10 && metrics.stringWidth(text) > maxWidth) {
            size -= 1;
            metrics = fontMetrics(family, size);
        }
        return new TextMetrics(size, metrics.stringWidth(text), metrics.getAscent(), metrics.getDescent());
    }

    private static FontMetrics fontMetrics(String family, int size) {
        Font font = new Font(family, Font.PLAIN, size);
        METRIC_GRAPHICS.setFont(font);
        return METRIC_GRAPHICS.getFontMetrics(font);
    }

    private static String cdata(String text) {
        return "<![CDATA[" + text.replace("]]>", "]]]]><![CDATA[>") + "]]>";
    }

    private static String escapeAttr(String text) {
        return text.replace("&", "&amp;")
                .replace("'", "&apos;")
                .replace("\"", "&quot;")
                .replace("<", "&lt;")
                .replace(">", "&gt;");
    }

    private static void appendf(StringBuilder builder, String fmt, Object... args) {
        builder.append(String.format(Locale.US, fmt, args));
    }

    private static double pxX(int x, double scale) {
        return (x + PAD_X) * CELL_W * scale;
    }

    private static double pxY(int y, double scale) {
        return (y + PAD_Y) * CELL_H * scale;
    }

    private static ShapeGeometry buildGeometry(DiagramShape shape, double scale, boolean fixedSlope) {
        double x0 = pxX(shape.x0, scale);
        double y0 = pxY(shape.y0, scale);
        double x1 = pxX(shape.x1, scale);
        double y1 = pxY(shape.y1, scale);
        double width = x1 - x0;
        double height = y1 - y0;
        double cx = (x0 + x1) / 2.0;
        double cy = (y0 + y1) / 2.0;

        switch (shape.kind) {
            case RECT:
                if (shape.rounded) {
                    double r = 5.0 * scale;
                    Path2D.Double rounded = new Path2D.Double();
                    rounded.moveTo(x0 + r, y0);
                    rounded.lineTo(x1 - r, y0);
                    rounded.quadTo(x1, y0, x1, y0 + r);
                    rounded.lineTo(x1, y1 - r);
                    rounded.quadTo(x1, y1, x1 - r, y1);
                    rounded.lineTo(x0 + r, y1);
                    rounded.quadTo(x0, y1, x0, y1 - r);
                    rounded.lineTo(x0, y0 + r);
                    rounded.quadTo(x0, y0, x0 + r, y0);
                    rounded.closePath();
                    String svg = String.format(
                            Locale.US,
                            "M%.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f z",
                            x0 + r, y0, x1 - r, y0, x1, y0, x1, y0 + r, x1, y1 - r, x1, y1, x1 - r, y1,
                            x0 + r, y1, x0, y1, x0, y1 - r, x0, y0 + r, x0, y0, x0 + r, y0);
                    return new ShapeGeometry(rounded, svg, rounded);
                }
                Rectangle2D.Double rect = new Rectangle2D.Double(x0, y0, width, height);
                String rectSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                        x0, y0, x1, y0, x1, y1, x0, y1);
                return new ShapeGeometry(rect, rectSvg, rect);
            case DOCUMENT:
                double dx = width / 6.0;
                double wave = 8.0 * scale;
                Path2D.Double document = new Path2D.Double();
                document.moveTo(x0, y0);
                document.lineTo(x1, y0);
                document.lineTo(x1, y1);
                document.quadTo(cx + dx, y1 - wave, cx, y1);
                document.quadTo(cx - dx, y1 + wave, x0, y1);
                document.closePath();
                String documentSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f L%.1f %.1f Q%.1f %.1f %.1f %.1f Q%.1f %.1f %.1f %.1f z",
                        x0, y0, x1, y0, x1, y1, cx + dx, y1 - wave, cx, y1, cx - dx, y1 + wave, x0, y1);
                return new ShapeGeometry(document, documentSvg, document);
            case ELLIPSE:
                Ellipse2D.Double ellipse = new Ellipse2D.Double(x0, y0, width, height);
                double rx = width / 2.0;
                double ry = height / 2.0;
                double k = 0.5522847;
                String ellipseSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f C%.5f %.1f %.1f %.5f %.1f %.1f C%.1f %.5f %.5f %.1f %.1f %.1f C%.5f %.1f %.1f %.5f %.1f %.1f C%.1f %.5f %.5f %.1f %.1f %.1f z",
                        cx, y0, cx + rx * k, y0, x1, cy - ry * k, x1, cy, x1, cy + ry * k, cx + rx * k, y1,
                        cx, y1, cx - rx * k, y1, x0, cy + ry * k, x0, cy, x0, cy - ry * k, cx - rx * k, y0,
                        cx, y0);
                return new ShapeGeometry(ellipse, ellipseSvg, ellipse);
            case DECISION:
                Path2D.Double diamond = new Path2D.Double();
                diamond.moveTo(x0, cy);
                diamond.lineTo(cx, y0);
                diamond.lineTo(x1, cy);
                diamond.lineTo(cx, y1);
                diamond.closePath();
                String diamondSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                        x0, cy, cx, y0, x1, cy, cx, y1);
                return new ShapeGeometry(diamond, diamondSvg, diamond);
            case MANUAL_OPERATION: {
                double slope = 10.0 * scale;
                Path2D.Double manual = new Path2D.Double();
                manual.moveTo(x0 - slope / 2.0, y0);
                manual.lineTo(x1 + slope / 2.0, y0);
                manual.lineTo(x1 - slope / 2.0, y1);
                manual.lineTo(x0 + slope / 2.0, y1);
                manual.closePath();
                String manualSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                        x0 - slope / 2.0, y0, x1 + slope / 2.0, y0, x1 - slope / 2.0, y1, x0 + slope / 2.0, y1);
                return new ShapeGeometry(manual, manualSvg, manual);
            }
            case TRAPEZOID: {
                double slope = fixedSlope ? 10.0 * scale : 10.0 * scale;
                Path2D.Double trapezoid = new Path2D.Double();
                trapezoid.moveTo(x0 + slope / 2.0, y0);
                trapezoid.lineTo(x1 - slope / 2.0, y0);
                trapezoid.lineTo(x1 + slope / 2.0, y1);
                trapezoid.lineTo(x0 - slope / 2.0, y1);
                trapezoid.closePath();
                String trapezoidSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                        x0 + slope / 2.0, y0, x1 - slope / 2.0, y0, x1 + slope / 2.0, y1, x0 - slope / 2.0, y1);
                return new ShapeGeometry(trapezoid, trapezoidSvg, trapezoid);
            }
            case IO: {
                double slope = fixedSlope ? 10.0 * scale : 10.0 * scale;
                Path2D.Double io = new Path2D.Double();
                io.moveTo(x0 + slope / 2.0, y0);
                io.lineTo(x1 + slope / 2.0, y0);
                io.lineTo(x1 - slope / 2.0, y1);
                io.lineTo(x0 - slope / 2.0, y1);
                io.closePath();
                String ioSvg = String.format(
                        Locale.US,
                        "M%.1f %.1f L%.1f %.1f L%.1f %.1f L%.1f %.1f z",
                        x0 + slope / 2.0, y0, x1 + slope / 2.0, y0, x1 - slope / 2.0, y1, x0 - slope / 2.0, y1);
                return new ShapeGeometry(io, ioSvg, io);
            }
            case STORAGE:
                return buildStorageGeometry(x0, y0, x1, y1, width, scale);
            default:
                throw new IllegalStateException();
        }
    }

    private static ShapeGeometry buildStorageGeometry(double x0, double y0, double x1, double y1, double width, double scale) {
        double top = 7.0 * scale;
        double bottom = 10.0 * scale;
        double inset = width / 6.0;
        Path2D.Double outline = new Path2D.Double();
        outline.moveTo(x0, y0);
        outline.curveTo(x0 + inset, y0 + top, x1 - inset, y0 + top, x1, y0);
        outline.curveTo(x1 - inset, y0 - top, x0 + inset, y0 - top, x0, y0);
        outline.moveTo(x0, y0);
        outline.lineTo(x0, y1);
        outline.curveTo(x0 + inset, y1 + bottom, x1 - inset, y1 + bottom, x1, y1);
        outline.lineTo(x1, y0);

        Path2D.Double shadow = new Path2D.Double();
        shadow.moveTo(x0, y0);
        shadow.curveTo(x0 + inset, y0 - top, x1 - inset, y0 - top, x1, y0);
        shadow.lineTo(x1, y1);
        shadow.curveTo(x1 - inset, y1 + bottom, x0 + inset, y1 + bottom, x0, y1);
        shadow.closePath();

        String svg = String.format(
                Locale.US,
                "M%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f M%.1f %.1f L%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f L%.1f %.1f ",
                x0, y0, x0 + inset, y0 + top, x1 - inset, y0 + top, x1, y0,
                x1 - inset, y0 - top, x0 + inset, y0 - top, x0, y0,
                x0, y0, x0, y1, x0 + inset, y1 + bottom, x1 - inset, y1 + bottom, x1, y1, x1, y0);
        return new ShapeGeometry(outline, svg, shadow);
    }

    private static void renderPng(Diagram diagram, CliOptions options, Path output) throws Exception {
        int width = (int) Math.round((diagram.width + 4.0) * CELL_W * options.scale);
        int height = (int) Math.round((diagram.height + 4.0) * CELL_H * options.scale);
        boolean alpha = options.transparent || options.background.a < 255;
        BufferedImage image = new BufferedImage(
                width,
                height,
                alpha ? BufferedImage.TYPE_INT_ARGB : BufferedImage.TYPE_INT_RGB);
        Graphics2D g = image.createGraphics();
        try {
            applyRenderingHints(g, options.noAntialias);
            if (!options.transparent) {
                g.setColor(options.background.toAwtColor());
                g.fillRect(0, 0, width, height);
            }
            if (options.debug) {
                drawDebugGrid(g, width, height, options.scale);
            }
            if (!options.noShadows) {
                drawShadows(image, diagram, options);
                g = image.createGraphics();
                applyRenderingHints(g, options.noAntialias);
            }
            for (Separation separation : diagram.separations) {
                g.setColor(java.awt.Color.WHITE);
                g.setStroke(new BasicStroke((float) (3.0 * options.scale), BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER));
                if (separation.vertical) {
                    g.draw(new Line2D.Double(
                            pxX(separation.coord, options.scale),
                            pxY(separation.start, options.scale),
                            pxX(separation.coord, options.scale),
                            pxY(separation.end, options.scale)));
                } else {
                    g.draw(new Line2D.Double(
                            pxX(separation.start, options.scale),
                            pxY(separation.coord, options.scale),
                            pxX(separation.end, options.scale),
                            pxY(separation.coord, options.scale)));
                }
            }
            for (DiagramShape shape : diagram.shapes) {
                drawShape(g, shape, options);
            }
            for (StrokePathInfo path : diagram.paths) {
                drawPath(g, path, options);
            }
            for (GridPoint marker : diagram.markers) {
                drawMarker(g, marker, options.scale);
            }
            for (DiagramShape shape : diagram.shapes) {
                drawShapeText(g, shape, options);
            }
            for (LooseText text : diagram.looseTexts) {
                drawLooseText(g, text, options);
            }
        } finally {
            g.dispose();
        }
        String lower = output.getFileName().toString().toLowerCase(Locale.ROOT);
        ImageIO.write(image, lower.endsWith(".gif") ? "gif" : "png", output.toFile());
    }

    private static void applyRenderingHints(Graphics2D g, boolean noAntialias) {
        g.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING,
                noAntialias ? RenderingHints.VALUE_ANTIALIAS_OFF : RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(
                RenderingHints.KEY_TEXT_ANTIALIASING,
                noAntialias
                        ? RenderingHints.VALUE_TEXT_ANTIALIAS_OFF
                        : RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_NORMALIZE);
    }

    private static void drawDebugGrid(Graphics2D g, int width, int height, double scale) {
        g.setColor(new java.awt.Color(102, 102, 102));
        g.setStroke(new BasicStroke(0.5f));
        for (double x = 0; x <= width; x += CELL_W * scale) {
            g.draw(new Line2D.Double(x, 0, x, height));
        }
        for (double y = 0; y <= height; y += CELL_H * scale) {
            g.draw(new Line2D.Double(0, y, width, y));
        }
    }

    private static void drawShadows(BufferedImage target, Diagram diagram, CliOptions options) {
        BufferedImage shadow = new BufferedImage(target.getWidth(), target.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = shadow.createGraphics();
        try {
            applyRenderingHints(g, false);
            g.setComposite(AlphaComposite.SrcOver);
            g.setColor(new java.awt.Color(128, 128, 128, 180));
            AffineTransform shift = AffineTransform.getTranslateInstance(5.0 * options.scale, 5.0 * options.scale);
            for (DiagramShape shape : diagram.shapes) {
                ShapeGeometry geometry = buildGeometry(shape, options.scale, options.fixedSlope);
                Shape shadowShape = shift.createTransformedShape(geometry.shadowShape);
                g.fill(shadowShape);
            }
        } finally {
            g.dispose();
        }
        shadow = blur(shadow);
        Graphics2D onto = target.createGraphics();
        try {
            onto.drawImage(shadow, 0, 0, null);
        } finally {
            onto.dispose();
        }
    }

    private static BufferedImage blur(BufferedImage image) {
        float[] kernel = new float[25];
        Arrays.fill(kernel, 1.0f / 25.0f);
        ConvolveOp op = new ConvolveOp(new Kernel(5, 5, kernel), ConvolveOp.EDGE_NO_OP, null);
        BufferedImage first = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
        op.filter(image, first);
        BufferedImage second = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
        op.filter(first, second);
        return second;
    }

    private static void drawShape(Graphics2D g, DiagramShape shape, CliOptions options) {
        ShapeGeometry geometry = buildGeometry(shape, options.scale, options.fixedSlope);
        if (shape.kind == ShapeKind.STORAGE) {
            drawStorage(g, shape, geometry, options.scale);
            return;
        }
        g.setColor(shape.fill.toAwtColor());
        g.fill(geometry.fillShape);
        g.setColor(java.awt.Color.BLACK);
        g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.draw(geometry.fillShape);
    }

    private static void drawStorage(Graphics2D g, DiagramShape shape, ShapeGeometry geometry, double scale) {
        double x0 = pxX(shape.x0, scale);
        double y0 = pxY(shape.y0, scale);
        double x1 = pxX(shape.x1, scale);
        double y1 = pxY(shape.y1, scale);
        double width = x1 - x0;
        double inset = width / 6.0;
        double top = 7.0 * scale;
        double bottom = 10.0 * scale;

        g.setColor(shape.fill.toAwtColor());
        g.fill(new Rectangle2D.Double(x0, y0, width, y1 - y0));
        g.fill(new Ellipse2D.Double(x0, y0 - top, width, top * 2.0));
        g.fill(new Ellipse2D.Double(x0, y1 - bottom, width, bottom * 2.0));

        g.setColor(java.awt.Color.BLACK);
        g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.draw(new Arc2D.Double(x0, y0 - top, width, top * 2.0, 0, 360, Arc2D.OPEN));
        g.draw(new Line2D.Double(x0, y0, x0, y1));
        g.draw(new Line2D.Double(x1, y0, x1, y1));
        Path2D.Double bottomArc = new Path2D.Double();
        bottomArc.moveTo(x0, y1);
        bottomArc.curveTo(x0 + inset, y1 + bottom, x1 - inset, y1 + bottom, x1, y1);
        g.draw(bottomArc);
        g.draw(geometry.shadowShape);
    }

    private static void drawPath(Graphics2D g, StrokePathInfo path, CliOptions options) {
        if (path.points.size() < 2) {
            return;
        }
        Path2D.Double awtPath = new Path2D.Double();
        for (int i = 0; i < path.points.size(); i++) {
            GridPoint point = path.points.get(i);
            double x = pxX(point.x, options.scale);
            double y = pxY(point.y, options.scale);
            if (i == 0) {
                awtPath.moveTo(x, y);
            } else {
                awtPath.lineTo(x, y);
            }
        }
        g.setColor(java.awt.Color.BLACK);
        if (path.dashed) {
            g.setStroke(new BasicStroke(
                    1.0f,
                    BasicStroke.CAP_BUTT,
                    BasicStroke.JOIN_ROUND,
                    0,
                    new float[] {5.0f, 5.0f},
                    0));
        } else {
            g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        }
        g.draw(awtPath);
        if (path.arrowStart != null) {
            drawArrow(g, path.points.get(0), path.arrowStart, options.scale);
        }
        if (path.arrowEnd != null) {
            drawArrow(g, path.points.get(path.points.size() - 1), path.arrowEnd, options.scale);
        }
    }

    private static void drawArrow(Graphics2D g, GridPoint point, ArrowDir dir, double scale) {
        double x = pxX(point.x, scale);
        double y = pxY(point.y, scale);
        double[] c = arrowCoords(x, y, dir, scale);
        Path2D.Double triangle = new Path2D.Double();
        triangle.moveTo(c[0], c[1]);
        triangle.lineTo(c[2], c[3]);
        triangle.lineTo(c[4], c[5]);
        triangle.closePath();
        g.setColor(java.awt.Color.BLACK);
        g.fill(triangle);
    }

    private static double[] arrowCoords(double x, double y, ArrowDir dir, double scale) {
        switch (dir) {
            case RIGHT:
                return new double[] {x + 5.0 * scale, y, x - 5.0 * scale, y - 7.0 * scale, x - 5.0 * scale,
                        y + 7.0 * scale};
            case LEFT:
                return new double[] {x - 5.0 * scale, y, x + 5.0 * scale, y - 7.0 * scale, x + 5.0 * scale,
                        y + 7.0 * scale};
            case UP:
                return new double[] {x, y - 7.0 * scale, x - 5.0 * scale, y + 7.0 * scale, x + 5.0 * scale,
                        y + 7.0 * scale};
            case DOWN:
                return new double[] {x, y + 7.0 * scale, x - 5.0 * scale, y - 7.0 * scale, x + 5.0 * scale,
                        y - 7.0 * scale};
            default:
                throw new IllegalStateException();
        }
    }

    private static void drawMarker(Graphics2D g, GridPoint point, double scale) {
        double r = 4.0 * scale;
        double x = pxX(point.x, scale) - r;
        double y = pxY(point.y, scale) - r;
        Ellipse2D.Double marker = new Ellipse2D.Double(x, y, r * 2.0, r * 2.0);
        g.setColor(java.awt.Color.WHITE);
        g.fill(marker);
        g.setColor(java.awt.Color.BLACK);
        g.setStroke(new BasicStroke(1.0f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.draw(marker);
    }

    private static void drawShapeText(Graphics2D g, DiagramShape shape, CliOptions options) {
        String family = options.svgFontUrl != null ? "Courier" : "Courier";
        for (TextLayout layout : layoutShapeText(shape, options.scale, family)) {
            Font font = new Font(family, Font.PLAIN, layout.fontSize);
            g.setFont(font);
            g.setColor(shape.textColor.toAwtColor());
            if (layout.bullet) {
                double d = layout.bulletRadius * 2.0;
                g.fill(new Ellipse2D.Double(layout.bulletX - layout.bulletRadius,
                        layout.baseline - layout.bulletRadius * 0.8, d, d));
            }
            g.drawString(layout.text, (float) layout.x, (float) layout.baseline);
        }
    }

    private static void drawLooseText(Graphics2D g, LooseText text, CliOptions options) {
        String family = "Courier";
        TextMetrics metrics = measureAndFit(
                text.text,
                pxX(text.end, options.scale) - pxX(text.start, options.scale),
                family,
                BASE_FONT_SIZE);
        double centerX = (pxX(text.start, options.scale) + pxX(text.end, options.scale)) / 2.0;
        double x = centerX - metrics.width / 2.0;
        double baseline = pxY(text.row, options.scale) + metrics.baselineOffset();
        g.setFont(new Font(family, Font.PLAIN, metrics.fontSize));
        g.setColor(java.awt.Color.BLACK);
        g.drawString(text.text, (float) x, (float) baseline);
    }

    private static String circlePath(double centerX, double centerY, double r) {
        return String.format(
                Locale.US,
                "M%.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f C%.1f %.1f %.1f %.1f %.1f %.1f z",
                centerX,
                centerY,
                centerX + r * 0.5523,
                centerY,
                centerX + r,
                centerY + r * 0.4477,
                centerX + r,
                centerY + r,
                centerX + r,
                centerY + r * 1.5523,
                centerX + r * 0.5523,
                centerY + r * 2.0,
                centerX,
                centerY + r * 2.0,
                centerX - r * 0.5523,
                centerY + r * 2.0,
                centerX - r,
