    private static final class ParseOutcome {
        final OutcomeKind kind;
        final CliOptions options;

        private ParseOutcome(OutcomeKind kind, CliOptions options) {
            this.kind = kind;
            this.options = options;
        }

        static ParseOutcome usage() {
            return new ParseOutcome(OutcomeKind.USAGE, null);
        }

